class Solution:
    def minOperations(self, nums1: List[int], nums2: List[int], k: int) -> int:
        if k == 0:
            if nums1 == nums2:
                return 0
            else:
                return -1

        pos_ops = 0
        neg_ops = 0

        for i in range(len(nums1)):
            diff = nums2[i] - nums1[i]
            if diff % k != 0:
