    def isPossibleToCutPath(self, grid: List[List[int]]) -> bool:
        m, n = len(grid), len(grid[0])

        def check_path() -> bool:
            stack = [(0, 0)]
            while stack:
                r, c = stack.pop()
                # If we reached the bottom-right corner, a path exists
                if r == m - 1 and c == n - 1:
                    return True

                # Mark the current cell as visited (0) to avoid revisiting 
                # and to effectively remove it from the grid for the next path search
