                # Push right and down cells to the stack if they are within bounds and have value 1
                # We push right first so that down is popped first, maintaining a consistent path-finding order
                if c + 1 < n and grid[r][c+1] == 1:
                    stack.append((r, c+1))
                if r + 1 < m and grid[r+1][c] == 1:
                    stack.append((r+1, c))

            return False

        # First pass: try to find a path and mark its cells as 0
        if not check_path():
            return True

        # Restore the start cell since we are not allowed to flip (0, 0)
        grid[0][0] = 1

        # Second pass: try to find another path. 
        # If we can't find a second path, it means all paths share at least one common cell (a cut vertex),
        # so we can disconnect the matrix by flipping that cell.
        return not check_path()

