    def minimumScore(self, s: str, t: str) -> int:
        n = len(s)
        m = len(t)

        # pref[i] will store the minimum index in s such that t[:i] is a subsequence of s[:pref[i]+1]
        pref = [float('inf')] * (m + 1)
        pref[0] = -1
        ptr = 0
        for i in range(m):
            while ptr < n and s[ptr] != t[i]:
                ptr += 1
            if ptr < n:
                pref[i+1] = ptr
                ptr += 1
            else:
                break

        # suff[j] will store the maximum index in s such that t[j:] is a subsequence of s[suff[j]:]
