class Solution:
    def findTheString(self, lcp: List[List[int]]) -> str:
        n = len(lcp)
        word = []
        next_char = 0  # 0 represents 'a', 1 represents 'b', etc.

        # Step 1: Greedily construct the lexicographically smallest string
        for i in range(n):
            found = False
            for j in range(i):
                if lcp[j][i] > 0:
                    word.append(word[j])
                    found = True
                    break
            if not found:
                if next_char >= 26:
                    return ""  # Need more than 26 distinct characters
                word.append(chr(ord('a') + next_char))
                next_char += 1

        # Step 2: Verify by computing the actual LCP matrix
        actual_lcp = [[0] * n for _ in range(n)]
        for i in range(n - 1, -1, -1):
            for j in range(n - 1, -1, -1):
                if word[i] == word[j]:
                    if i + 1 < n and j + 1 < n:
                        actual_lcp[i][j] = 1 + actual_lcp[i + 1][j + 1]
                    else:
                        actual_lcp[i][j] = 1
                else:
                    actual_lcp[i][j] = 0

        # Step 3: Compare actual LCP with given LCP
