class Solution:
    def rootCount(self, edges: List[List[int]], guesses: List[List[int]], k: int) -> int:
        n = len(edges) + 1
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        guess_set = set()
        for u, v in guesses:
            guess_set.add((u, v))

        # First DFS: root at 0, count correct guesses
        correct = 0
        visited = [False] * n
        visited[0] = True
        stack = [0]

        while stack:
            u = stack.pop()
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    if (u, v) in guess_set:
                        correct += 1
                    stack.append(v)

        # Second DFS: re-root and update correct count
        result = 0
        visited = [False] * n
        visited[0] = True
        stack = [(0, correct)]

        while stack:
            u, curr_correct = stack.pop()
            if curr_correct >= k:
                result += 1
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    new_correct = curr_correct
                    # Edge (u, v) flips to (v, u) when v becomes root
                    if (u, v) in guess_set:
                        new_correct -= 1
                    if (v, u) in guess_set:
                        new_correct += 1
                    stack.append((v, new_correct))

        return result

