class Solution:
    def waysToReachTarget(self, target: int, types: List[List[int]]) -> int:
        MOD = 10**9 + 7
        dp = [0] * (target + 1)
        dp[0] = 1

        for count, marks in types:
            new_dp = [0] * (target + 1)
            for j in range(target + 1):
                if dp[j]:
                    val = dp[j]
                    new_dp[j] = (new_dp[j] + val) % MOD
                    for k in range(1, count + 1):
                        nxt = j + k * marks
                        if nxt > target:
                            break
                        new_dp[nxt] = (new_dp[nxt] + val) % MOD
            dp = new_dp

        return dp[target]

