class Solution:
    def findMinimumTime(self, tasks: List[List[int]]) -> int:
        # Sort tasks by end time to process earlier-ending tasks first
        tasks.sort(key=lambda x: x[1])

        # Track which time points the computer is on
        on = [False] * 2001

        for start, end, duration in tasks:
            # Count how many time points in [start, end] are already on
            count = 0
            for t in range(start, end + 1):
                if on[t]:
                    count += 1

            remaining = duration - count

            # If we need more time points, pick the latest available ones
            if remaining > 0:
                for t in range(end, start - 1, -1):
                    if not on[t]:
                        on[t] = True
                        remaining -= 1
                        if remaining == 0:
                            break

        return sum(on)

