class Solution:
    def repairCars(self, ranks: List[int], cars: int) -> int:
        rank_counts = Counter(ranks)

        def can_repair(time: int) -> bool:
            total_cars = 0
            for r, count in rank_counts.items():
                total_cars += count * math.isqrt(time // r)
                if total_cars >= cars:
                    return True
            return False

