            # A valid knight move is either 2 steps in one direction and 1 in the other
            if not ((dr == 1 and dc == 2) or (dr == 2 and dc == 1)):
                return False

        return True

class Solution:
    def findSmallestInteger(self, nums: List[int], value: int) -> int:
        counts = [0] * value
        for x in nums:
            counts[x % value] += 1

        for i in range(len(nums) + 1):
            if counts[i % value] == 0:
                return i
            counts[i % value] -= 1

        return len(nums)

