class Solution:
    def makePrefSumNonNegative(self, nums: List[int]) -> int:
        prefix_sum = 0
        ops = 0
        min_heap = []

        for num in nums:
            prefix_sum += num
            if num < 0:
                heapq.heappush(min_heap, num)

            while prefix_sum < 0:
                smallest = heapq.heappop(min_heap)
                prefix_sum -= smallest
                ops += 1

        return ops

class Solution:
    def primeSubOperation(self, nums: List[int]) -> bool:
        # Sieve of Eratosthenes to find all primes up to 1000
        max_val = 1000
        is_prime = [True] * (max_val + 1)
        is_prime[0] = is_prime[1] = False
        for i in range(2, int(max_val**0.5) + 1):
            if is_prime[i]:
                for j in range(i * i, max_val + 1, i):
                    is_prime[j] = False

        primes = [i for i in range(2, max_val + 1) if is_prime[i]]

        prev = 0
        for num in nums:
            if num <= prev:
                return False

            # Find the largest prime strictly less than (num - prev)
            target = num - prev
            lo, hi = 0, len(primes) - 1
            best = -1
            while lo <= hi:
                mid = (lo + hi) // 2
                if primes[mid] < target:
                    best = primes[mid]
                    lo = mid + 1
                else:
                    hi = mid - 1

            # Subtract the largest valid prime if one exists
            if best != -1:
                num -= best

            prev = num

        return True

