class Solution:
    def collectTheCoins(self, coins: List[int], edges: List[List[int]]) -> int:
        n = len(coins)
        if n <= 2:
            return 0

        adj = [[] for _ in range(n)]
        degree = [0] * n

        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)
            degree[u] += 1
            degree[v] += 1

        # Step 1: Remove leaves without coins (cascade)
        queue = deque()
        for i in range(n):
            if degree[i] == 1 and coins[i] == 0:
                queue.append(i)

        removed = [False] * n
        while queue:
            u = queue.popleft()
            if removed[u]:
                continue
            removed[u] = True
            for v in adj[u]:
                if not removed[v]:
                    degree[v] -= 1
                    if degree[v] == 1 and coins[v] == 0:
                        queue.append(v)

        # Step 2: Remove 2 layers of leaves
        # Layer 1: find current leaves
        queue = deque()
        for i in range(n):
            if not removed[i] and degree[i] == 1:
                queue.append(i)

        layer2 = []
        while queue:
            u = queue.popleft()
            if removed[u]:
                continue
            removed[u] = True
            for v in adj[u]:
                if not removed[v]:
                    degree[v] -= 1
                    if degree[v] == 1:
                        layer2.append(v)

        # Layer 2: remove the new leaves
        for u in layer2:
            if not removed[u]:
                removed[u] = True
                for v in adj[u]:
                    if not removed[v]:
                        degree[v] -= 1

        # Count remaining edges
        remaining_edges = 0
        for i in range(n):
            if not removed[i]:
                remaining_edges += degree[i]
        remaining_edges //= 2

        return remaining_edges * 2

class Solution:
    def minimumTime(self, hens: List[int], grains: List[int]) -> int:
        hens.sort()
        grains.sort()
        m = len(grains)

        def check(T):
            j = 0
            for h in hens:
                if j >= m:
                    return True
                if grains[j] < h:
                    left_dist = h - grains[j]
                    if left_dist > T:
                        return False
                    # Max rightward reach after covering left_dist to the left
                    # Option 1: go left first, then right: time = 2*left_dist + right_dist <= T
                    # Option 2: go right first, then left: time = 2*right_dist + left_dist <= T
                    right_reach = max(T - 2 * left_dist, (T - left_dist) // 2)
                    max_pos = h + right_reach
                else:
                    # Grain is to the right (or at same position), just go right
                    max_pos = h + T

                # Cover all grains within reach
                while j < m and grains[j] <= max_pos:
                    j += 1
            return j >= m

        lo, hi = 0, 2 * 10**9
        while lo < hi:
            mid = (lo + hi) // 2
            if check(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

class Solution:
    def minNumber(self, nums1: List[int], nums2: List[int]) -> int:
        set1 = set(nums1)
        set2 = set(nums2)
        common = set1 & set2

        # If there's a common digit, the smallest one is the answer
        if common:
            return min(common)

        # Otherwise, form the smallest two-digit number
        min1 = min(nums1)
        min2 = min(nums2)

        if min1 < min2:
            return min1 * 10 + min2
        else:
            return min2 * 10 + min1

