class Solution:
    def maximumCostSubstring(self, s: str, chars: str, vals: List[int]) -> int:
        # Initialize the value of each character to its 1-indexed position in the alphabet
        val_map = {chr(i + ord('a')): i + 1 for i in range(26)}

        # Override the values for characters present in `chars`
        for c, v in zip(chars, vals):
            val_map[c] = v

        max_cost = 0
        current_cost = 0

        # Apply Kadane's algorithm to find the maximum subarray sum
        for c in s:
            current_cost += val_map[c]

            # If the current running sum drops below 0, reset it to 0 
            # (equivalent to starting a new substring from the next character)
            if current_cost < 0:
                current_cost = 0
            elif current_cost > max_cost:
                max_cost = current_cost

        return max_cost

