class Solution:
    def findShortestCycle(self, n: int, edges: List[List[int]]) -> int:
        adj = defaultdict(list)
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        min_cycle = float('inf')

        for i in range(n):
            # BFS from node i to find shortest cycle through i
            dist = [-1] * n
            dist[i] = 0
            queue = deque([(i, -1)])  # (current_node, parent_node)

            while queue:
                u, parent = queue.popleft()
                for v in adj[u]:
                    if dist[v] == -1:
                        dist[v] = dist[u] + 1
                        queue.append((v, u))
                    elif v != parent:
                        # Found a back edge -> cycle detected
                        cycle_length = dist[u] + dist[v] + 1
                        min_cycle = min(min_cycle, cycle_length)
                        # 3 is the minimum possible cycle length in a simple graph
                        if min_cycle == 3:
                            return 3

        return min_cycle if min_cycle != float('inf') else -1

class Solution:
    def findTheLongestBalancedSubstring(self, s: str) -> int:
        max_len = 0
        zeros = 0
        ones = 0

        for char in s:
            if char == '0':
                # If we encounter a '0' after some '1's, it means a new potential 
                # balanced substring is starting. We reset the counts.
                if ones > 0:
                    zeros = 1
                    ones = 0
                else:
                    zeros += 1
            else:
                ones += 1
                # The length of the balanced substring is 2 * min(zeros, ones)
                max_len = max(max_len, 2 * min(zeros, ones))

        return max_len

