class Solution:
    def beautifulPair(self, nums1: List[int], nums2: List[int]) -> List[int]:
        n = len(nums1)
        points = defaultdict(list)
        for i in range(n):
            points[(nums1[i], nums2[i])].append(i)

        # Check for duplicate points first. If there are any, the minimum distance is 0.
        # We just need to find the lexicographically smallest pair among all duplicates.
        best_pair = None
        for coords, indices in points.items():
            if len(indices) >= 2:
                indices.sort()
                p = (indices[0], indices[1])
                if best_pair is None or p < best_pair:
                    best_pair = p
        if best_pair is not None:
            return list(best_pair)

        # If no duplicates, the minimum distance is at least 1.
        # We can use a divide and conquer approach (similar to the classic closest pair of points).
        P = [(nums1[i], nums2[i], i) for i in range(n)]
        P.sort(key=lambda p: (p[0], p[1], p[2]))

        def solve(left, right):
            # Base case: brute force for small number of points
            if right - left <= 3:
                best_d = float('inf')
                best_p = None
                for i in range(left, right):
                    for j in range(i+1, right):
                        dx = abs(P[i][0] - P[j][0])
                        dy = abs(P[i][1] - P[j][1])
                        d = dx + dy
                        u, v = P[i][2], P[j][2]
                        if u > v:
                            u, v = v, u
                        p = (u, v)
                        if best_d > d or (best_d == d and best_p > p):
                            best_d = d
                            best_p = p
                return best_d, best_p

            mid = (left + right) // 2
            mid_x = P[mid][0]

            d1, p1 = solve(left, mid)
            d2, p2 = solve(mid, right)

            # Keep the better result from the two halves
            if d1 < d2 or (d1 == d2 and p1 < p2):
                d, p = d1, p1
            else:
                d, p = d2, p2

            # Build the strip of points around the dividing line
            strip = []
            for i in range(left, right):
                if abs(P[i][0] - mid_x) <= d:
                    strip.append(P[i])

            # Sort the strip by y-coordinate
            strip.sort(key=lambda pnt: pnt[1])

            # Check pairs within the strip
            for i in range(len(strip)):
                p1_x, p1_y, p1_id = strip[i]
                for j in range(i+1, len(strip)):
                    p2_x, p2_y, p2_id = strip[j]
                    dy = p2_y - p1_y

                    # Since points are sorted by y, if dy > d, the Manhattan distance will definitely be > d
                    if dy > d:
                        break

                    dist = abs(p1_x - p2_x) + dy

                    if dist < d:
                        d = dist
                        u, v = p1_id, p2_id
                        if u > v:
                            u, v = v, u
                        p = (u, v)
                    elif dist == d:
                        u, v = p1_id, p2_id
                        if u > v:
                            u, v = v, u
                        if (u, v) < p:
                            p = (u, v)

            return d, p

        _, ans = solve(0, n)
        return list(ans)

class Solution:
    def minimizeMax(self, nums: List[int], p: int) -> int:
        nums.sort()
        n = len(nums)

        def can_form_pairs(max_diff: int) -> bool:
            count = 0
            i = 0
            while i < n - 1:
                if nums[i + 1] - nums[i] <= max_diff:
                    count += 1
                    i += 2  # skip both elements in the pair
                else:
                    i += 1
                if count >= p:
                    return True
            return count >= p

        low, high = 0, nums[-1] - nums[0]

        while low < high:
            mid = (low + high) // 2
            if can_form_pairs(mid):
                high = mid      # mid is feasible, try smaller
            else:
                low = mid + 1   # mid is too small, need larger

        return low

