#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def replaceValueInTree(self, root: Optional[TreeNode]) -> Optional[TreeNode]:
        if not root:
            return None

        # The root has no cousins, so its value becomes 0
        root.val = 0
        queue = [root]

        while queue:
            next_level_sum = 0
            # First pass: calculate the sum of all node values in the next level
            for node in queue:
                if node.left:
                    next_level_sum += node.left.val
                if node.right:
                    next_level_sum += node.right.val

            next_queue = []
            # Second pass: update the values of the children and prepare the next queue
            for node in queue:
                sibling_sum = 0
                if node.left:
                    sibling_sum += node.left.val
                if node.right:
                    sibling_sum += node.right.val

                # The new value for a child is the total sum of the next level 
                # minus the sum of its parent's children (itself and its siblings)
                if node.left:
                    node.left.val = next_level_sum - sibling_sum
                    next_queue.append(node.left)
                if node.right:
                    node.right.val = next_level_sum - sibling_sum
                    next_queue.append(node.right)

            queue = next_queue

        return root

class Solution:
    def addMinimum(self, word: str) -> int:
        # We start with at least 1 group of "abc"
        groups = 1

        # Iterate through the string to count how many "abc" groups are needed
        for i in range(1, len(word)):
            # If the current character is not strictly greater than the previous one,
            # it cannot be part of the same "abc" sequence, so we start a new group.
            if word[i] <= word[i - 1]:
                groups += 1

        # The total length of the valid string is groups * 3.
        # The number of insertions is the difference between the valid length and original length.
        return groups * 3 - len(word)

