class Solution:
    def minOperations(self, nums: List[int]) -> int:
        n = len(nums)
        count_ones = nums.count(1)

        # If there are already 1s, each operation converts one non-1 to 1
        if count_ones > 0:
            return n - count_ones

        # Find the shortest subarray with GCD = 1
        min_len = float('inf')

        for i in range(n):
            current_gcd = nums[i]
            for j in range(i + 1, n):
                current_gcd = gcd(current_gcd, nums[j])
                if current_gcd == 1:
                    min_len = min(min_len, j - i + 1)
                    break  # No need to extend further; we want the shortest

        # If no subarray has GCD = 1, it's impossible
        if min_len == float('inf'):
            return -1

        # (min_len - 1) operations to create a 1, then (n - 1) to spread it
        return (min_len - 1) + (n - 1)

