class Solution:
    def countOperationsToEmptyArray(self, nums: List[int]) -> int:
        n = len(nums)
        # Original indices sorted by their corresponding values
        pos = sorted(range(n), key=lambda i: nums[i])

        # BIT (1-indexed internally), O(n) construction
        bit = [0] * (n + 1)
        for i in range(1, n + 1):
            bit[i] += 1
            p = i + (i & (-i))
            if p <= n:
                bit[p] += bit[i]

        def update(i, delta):
            i += 1  # convert to 1-indexed
            while i <= n:
                bit[i] += delta
                i += i & (-i)

        def query(i):
            # returns sum of elements in [0, i] (0-indexed)
            i += 1  # convert to 1-indexed
            s = 0
            while i > 0:
                s += bit[i]
                i -= i & (-i)
            return s

        ans = 0
        for i in range(n):
            t = pos[i]
            if i == 0:
                # Count remaining elements in [0, t)
                rot = query(t - 1) if t > 0 else 0
            else:
                p = pos[i - 1]
                if t > p:
                    # Count remaining in (p, t) = [p+1, t-1]
                    rot = query(t - 1) - query(p)
                else:
                    # Circular: (p, n-1] + [0, t-1]
                    rot = query(n - 1) - query(p)
                    if t > 0:
                        rot += query(t - 1)

            ans += rot + 1  # rotations + 1 removal
            update(t, -1)   # mark target as removed

        return ans

