            return 2
        return 0

class Solution:
    def smallestBeautifulString(self, s: str, k: int) -> str:
        n = len(s)
        arr = [ord(c) - ord('a') for c in s]

        i = n - 1
        arr[i] += 1  # Start by trying to increment the last character

        while 0 <= i < n:
            if arr[i] == k:
                # Exceeded available characters, backtrack
                i -= 1
                if i >= 0:
                    arr[i] += 1
            elif (i >= 1 and arr[i] == arr[i - 1]) or (i >= 2 and arr[i] == arr[i - 2]):
                # Creates a palindrome, try next character
                arr[i] += 1
            else:
                # Valid character found, move forward to fill remaining positions
                i += 1
                if i < n:
                    arr[i] = 0  # Start with smallest possible character

        if i < 0:
            return ""

        return ''.join(chr(c + ord('a')) for c in arr)

class Solution:
    def tourOfKnight(self, m: int, n: int, r: int, c: int) -> List[List[int]]:
        board = [[-1] * n for _ in range(m)]
        board[r][c] = 0

        moves = [(-2, -1), (-2, 1), (-1, -2), (-1, 2),
                 (1, -2), (1, 2), (2, -1), (2, 1)]

        def get_degree(r, c):
            """Count available (unvisited) moves from (r, c)"""
            count = 0
            for dr, dc in moves:
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n and board[nr][nc] == -1:
                    count += 1
            return count

        def backtrack(r, c, step):
            if step == m * n:
                return True

            # Collect all valid next moves
            next_moves = []
            for dr, dc in moves:
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n and board[nr][nc] == -1:
                    next_moves.append((nr, nc))

            # Warnsdorff's heuristic: try moves with fewest onward options first
            next_moves.sort(key=lambda x: get_degree(x[0], x[1]))

            for nr, nc in next_moves:
                board[nr][nc] = step
                if backtrack(nr, nc, step + 1):
                    return True
                board[nr][nc] = -1  # backtrack

            return False

        backtrack(r, c, 1)
        return board

class Solution:
    def colorTheArray(self, n: int, queries: List[List[int]]) -> List[int]:
        colors = [0] * n
        count = 0
        ans = []

        for index, color in queries:
            # Remove previous adjacent pairs if the current element was already colored
            if colors[index] != 0:
                if index > 0 and colors[index - 1] == colors[index]:
                    count -= 1
                if index < n - 1 and colors[index + 1] == colors[index]:
                    count -= 1

            # Update the color
            colors[index] = color

            # Add new adjacent pairs (color is guaranteed to be >= 1, so it's never 0 here)
            if index > 0 and colors[index - 1] == colors[index]:
                count += 1
            if index < n - 1 and colors[index + 1] == colors[index]:
                count += 1

            ans.append(count)

        return ans

