class Solution:
    def maximumOr(self, nums: List[int], k: int) -> int:
        n = len(nums)
        prefix = [0] * n
        suffix = [0] * n

        # Compute prefix ORs
        for i in range(1, n):
            prefix[i] = prefix[i-1] | nums[i-1]

        # Compute suffix ORs
        for i in range(n-2, -1, -1):
            suffix[i] = suffix[i+1] | nums[i+1]

        ans = 0
        # Try applying all k operations to each element
        for i in range(n):
            current_or = prefix[i] | suffix[i] | (nums[i] << k)
            if current_or > ans:
                ans = current_or

        return ans

class Solution:
    def circularGameLosers(self, n: int, k: int) -> List[int]:
        visited = [False] * n
        current = 0  # 0-indexed position (friend 1 is index 0)
        visited[current] = True

        i = 1
        while True:
            current = (current + i * k) % n
            if visited[current]:
                break
            visited[current] = True
            i += 1

        return [j + 1 for j in range(n) if not visited[j]]

