class Solution:
    def countCompleteComponents(self, n: int, edges: List[List[int]]) -> int:
        adj = [[] for _ in range(n)]
        degree = [0] * n

        # Build the adjacency list and calculate the degree of each vertex
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)
            degree[u] += 1
            degree[v] += 1

        visited = [False] * n
        ans = 0

        # Helper function to perform DFS and find all vertices in a connected component
        def dfs(u, comp):
            visited[u] = True
            comp.append(u)
            for v in adj[u]:
                if not visited[v]:
                    dfs(v, comp)

        # Iterate through all vertices to find connected components
        for i in range(n):
            if not visited[i]:
                comp = []
                dfs(i, comp)
                V = len(comp)

                # A component is complete if every vertex in it has a degree of V - 1
                if all(degree[v] == V - 1 for v in comp):
                    ans += 1

        return ans

class Solution:
    def punishmentNumber(self, n: int) -> int:
        def check(num, target):
            if target < 0:
                return False
            if num == 0:
                return target == 0

            d = 10
            while num > 0:
                rem = num % d
                if rem <= target:
                    if check(num // d, target - rem):
                        return True
                d *= 10
            return False

        ans = 0
        for i in range(1, n + 1):
            if check(i * i, i):
                ans += i * i
        return ans

