            dist[source] = 0
            parent_edge = [-1] * n
            pq = [(0, source)]

            while pq:
                d, u = heapq.heappop(pq)
                if d > dist[u]:
                    continue
                if u == destination:
                    break
                for v, edge_idx in adj[u]:
                    w = edges[edge_idx][2]
                    nd = d + w
                    if nd < dist[v]:
                        dist[v] = nd
                        parent_edge[v] = edge_idx
                        heapq.heappush(pq, (nd, v))

            return dist, parent_edge

        dist, parent_edge = dijkstra()

        if dist[destination] > target:
            return []

        while dist[destination] < target:
            curr = destination
            edge_to_increase = -1
            while curr != source:
                eidx = parent_edge[curr]
                if is_neg1[eidx]:
                    edge_to_increase = eidx
                    break
                u, v, w = edges[eidx]
                curr = v if u == curr else u

            if edge_to_increase == -1:
                return []

            diff = target - dist[destination]
            edges[edge_to_increase][2] += diff

            dist, parent_edge = dijkstra()

        return edges

