class Solution:
    def minOperations(self, nums: List[int], x: int, y: int) -> int:
        low = 0
        high = (max(nums) + y - 1) // y
        diff = x - y

        while low < high:
            mid = (low + high) // 2
            ky = mid * y

            total_c = 0
            for num in nums:
                if num > ky:
                    total_c += (num - ky + diff - 1) // diff
                    if total_c > mid:
                        break

            if total_c <= mid:
                high = mid
            else:
                low = mid + 1

        return low

