class Solution:
    def minExtraChar(self, s: str, dictionary: List[str]) -> int:
        n = len(s)
        # dp[i] will store the minimum extra characters in the prefix s[0:i]
        dp = [0] * (n + 1)
        word_set = set(dictionary)

        for i in range(1, n + 1):
            # By default, assume the current character s[i-1] is an extra character
            dp[i] = dp[i - 1] + 1

            # Check all possible suffixes of s[0:i] to see if they match a word in the dictionary
            for j in range(i):
                if s[j:i] in word_set:
                    dp[i] = min(dp[i], dp[j])

        return dp[n]

