class Solution:
    def canTraverseAllPairs(self, nums: List[int]) -> bool:
        n = len(nums)
        if n == 1:
            return True
        if 1 in nums:
            return False

        MAX_VAL = max(nums)

        # Smallest Prime Factor (SPF) sieve
        spf = list(range(MAX_VAL + 1))
        for i in range(2, int(MAX_VAL**0.5) + 1):
            if spf[i] == i:
                for j in range(i*i, MAX_VAL + 1, i):
                    if spf[j] == j:
                        spf[j] = i

        parent = list(range(MAX_VAL + 1))

        def find(i):
            root = i
            while parent[root] != root:
                root = parent[root]
            curr = i
            while curr != root:
                nxt = parent[curr]
                parent[curr] = root
                curr = nxt
            return root

        def union(i, j):
            root_i = find(i)
            root_j = find(j)
            if root_i != root_j:
                parent[root_i] = root_j

        all_primes = set()

        for x in nums:
            temp = x
            first_p = -1
            while temp > 1:
                p = spf[temp]
                all_primes.add(p)
                if first_p == -1:
                    first_p = p
                else:
                    union(first_p, p)
                while temp % p == 0:
                    temp //= p

        roots = set()
        for p in all_primes:
            roots.add(find(p))

        return len(roots) <= 1

