class Solution:
    def maxIncreasingCells(self, mat: List[List[int]]) -> int:
        m = len(mat)
        n = len(mat[0])

        # Group cells by their values
        val_to_cells = defaultdict(list)
        for i in range(m):
            for j in range(n):
                val_to_cells[mat[i][j]].append((i, j))

        # Process values in increasing order
        sorted_vals = sorted(val_to_cells.keys())

        row_max = [0] * m
        col_max = [0] * n

        ans = 0

        for val in sorted_vals:
            cells = val_to_cells[val]
            # First, compute dp values for all cells with this value
            dp_updates = []
            for i, j in cells:
                dp_val = 1 + max(row_max[i], col_max[j])
                dp_updates.append((i, j, dp_val))
                if dp_val > ans:
                    ans = dp_val

            # Then, update row_max and col_max after all cells in this group are computed
            for i, j, dp_val in dp_updates:
                if dp_val > row_max[i]:
                    row_max[i] = dp_val
                if dp_val > col_max[j]:
                    col_max[j] = dp_val

        return ans

