class Solution:
    def matrixSumQueries(self, n: int, queries: List[List[int]]) -> int:
        seen_rows = [False] * n
        seen_cols = [False] * n
        count_rows = 0
        count_cols = 0
        total_sum = 0

        # Process queries in reverse order
        for t, idx, val in reversed(queries):
            if t == 0:
                if not seen_rows[idx]:
                    seen_rows[idx] = True
                    count_rows += 1
                    # The number of valid columns is n - count_cols
                    total_sum += val * (n - count_cols)
            else:
                if not seen_cols[idx]:
                    seen_cols[idx] = True
                    count_cols += 1
                    # The number of valid rows is n - count_rows
                    total_sum += val * (n - count_rows)

        return total_sum

class Solution:
    def count(self, num1: str, num2: str, min_sum: int, max_sum: int) -> int:
        MOD = 10**9 + 7

        def solve(num_str):
            n = len(num_str)
            memo = {}

            def dp(pos, dsum, tight):
                if dsum > max_sum:
                    return 0
                if pos == n:
                    return 1 if min_sum <= dsum <= max_sum else 0

                state = (pos, dsum, 1 if tight else 0)
                if state in memo:
                    return memo[state]

                limit = int(num_str[pos]) if tight else 9
                res = 0
                for d in range(limit + 1):
                    new_tight = tight and (d == limit)
                    res = (res + dp(pos + 1, dsum + d, new_tight)) % MOD

                memo[state] = res
                return res

            return dp(0, 0, True)

        # Compute num1 - 1 as a string
        num1_int = int(num1) - 1
        num1_minus_1 = str(num1_int)

        ans = (solve(num2) - solve(num1_minus_1)) % MOD
        return ans

