class Solution:
    def smallestString(self, s: str) -> str:
        n = len(s)
        s_list = list(s)

        # Find the first character that is not 'a'
        i = 0
        while i < n and s_list[i] == 'a':
            i += 1

        # If the string consists entirely of 'a's, 
        # we must perform the operation on a non-empty substring.
        # To make it lexicographically smallest, we change the last 'a' to 'z'.
        if i == n:
            s_list[-1] = 'z'
        else:
            # Otherwise, we start the operation at the first non-'a' character 
            # and continue until we hit an 'a' or the end of the string.
            while i < n and s_list[i] != 'a':
                s_list[i] = chr(ord(s_list[i]) - 1)
                i += 1

        return "".join(s_list)

