class Solution:
    def minCost(self, nums: List[int], x: int) -> int:
        n = len(nums)
        current_min = nums[:]
        current_sum = sum(nums)
        ans = current_sum

        for k in range(1, n):
            # Update the minimum costs for each chocolate type after k operations
            for j in range(k):
                val = nums[n - k + j]
                if val < current_min[j]:
                    current_sum += val - current_min[j]
                    current_min[j] = val
            for j in range(k, n):
                val = nums[j - k]
                if val < current_min[j]:
                    current_sum += val - current_min[j]
                    current_min[j] = val

            # Calculate the total cost if we stop after k operations
            cost = current_sum + k * x
            if cost < ans:
                ans = cost

        return ans

