class Solution:
    def specialPerm(self, nums: List[int]) -> int:
        n = len(nums)
        MOD = 10**9 + 7

        # dp[mask][last] = number of special permutations using elements in mask,
        # ending with the element at index 'last'
        dp = [[0] * n for _ in range(1 << n)]

        # Base case: each single element is a valid starting permutation
        for i in range(n):
            dp[1 << i][i] = 1

        # Fill DP table
        for mask in range(1, 1 << n):
            for last in range(n):
                if dp[mask][last] == 0:
                    continue
                if not (mask & (1 << last)):
                    continue
                for j in range(n):
                    if mask & (1 << j):
                        continue
                    # Check divisibility condition
                    if nums[last] % nums[j] == 0 or nums[j] % nums[last] == 0:
                        new_mask = mask | (1 << j)
                        dp[new_mask][j] = (dp[new_mask][j] + dp[mask][last]) % MOD

        # Sum all complete permutations (all elements used)
        full_mask = (1 << n) - 1
        ans = 0
        for i in range(n):
            ans = (ans + dp[full_mask][i]) % MOD

        return ans

class Solution:
    def paintWalls(self, cost: List[int], time: List[int]) -> int:
        n = len(cost)
        # dp[j] = minimum cost to cover at least j walls
        dp = [float('inf')] * (n + 1)
        dp[0] = 0

        for i in range(n):
            w = 1 + time[i]  # walls covered if paid painter paints wall i
            c = cost[i]
            # Iterate backwards to ensure each wall is used at most once (0/1 knapsack)
            for j in range(n, -1, -1):
                if dp[j] != float('inf'):
                    new_j = min(n, j + w)
                    if dp[j] + c < dp[new_j]:
                        dp[new_j] = dp[j] + c

        return dp[n]

