class Solution:
    def minimizeConcatenatedLength(self, words: List[str]) -> int:
        n = len(words)
        total_len = sum(len(w) for w in words)

        # dp[f][l] = max savings with first char f and last char l
        # -1 means unreachable state
        dp = [[-1] * 26 for _ in range(26)]

        f0 = ord(words[0][0]) - ord('a')
        l0 = ord(words[0][-1]) - ord('a')
        dp[f0][l0] = 0

        for i in range(1, n):
            fi = ord(words[i][0]) - ord('a')
            li = ord(words[i][-1]) - ord('a')

            new_dp = [[-1] * 26 for _ in range(26)]

            for f in range(26):
                for l in range(26):
                    if dp[f][l] == -1:
                        continue

                    # Option 1: append words[i] -> join(str, words[i])
                    # New first char: f, New last char: li
                    save1 = 1 if l == fi else 0
                    if dp[f][l] + save1 > new_dp[f][li]:
                        new_dp[f][li] = dp[f][l] + save1

                    # Option 2: prepend words[i] -> join(words[i], str)
                    # New first char: fi, New last char: l
                    save2 = 1 if li == f else 0
                    if dp[f][l] + save2 > new_dp[fi][l]:
                        new_dp[fi][l] = dp[f][l] + save2

            dp = new_dp

        max_savings = 0
        for f in range(26):
            for l in range(26):
                if dp[f][l] > max_savings:
                    max_savings = dp[f][l]

        return total_len - max_savings

