        n = len(nums)
        total_imbalance = 0
        seen = [0] * (n + 1)

        for i in range(n):
            current_min = nums[i]
            current_max = nums[i]
            distinct_count = 1
            marker = i + 1
            seen[nums[i]] = marker

            for j in range(i + 1, n):
                val = nums[j]
                if val < current_min:
                    current_min = val
                elif val > current_max:
                    current_max = val

                if seen[val] != marker:
