        stack = []
        for node_id, parent_id in nodes:
            if not stack:
                if parent_id == -1:
                    stack.append(node_id)
                else:
                    return False
            else:
                while stack and stack[-1] != parent_id:
                    stack.pop()
                if not stack:
                    return False
                stack.append(node_id)
