class Solution:
    def minimumBeautifulSubstrings(self, s: str) -> int:
        # Precompute binary representations of powers of 5 up to 15 bits
        powers_of_5 = set()
        val = 1
        while val <= (1 << 15):
            powers_of_5.add(bin(val)[2:])
            val *= 5

        n = len(s)
        dp = [float('inf')] * (n + 1)
        dp[n] = 0  # base case: empty suffix needs 0 substrings

        # Fill DP from right to left
        for i in range(n - 1, -1, -1):
            if s[i] == '0':
                # Can't start a beautiful substring with '0' (leading zero)
                continue
            for p in powers_of_5:
                length = len(p)
                if i + length <= n and s[i:i + length] == p:
                    dp[i] = min(dp[i], 1 + dp[i + length])

        return dp[0] if dp[0] != float('inf') else -1

class Solution:
    def countBlackBlocks(self, m: int, n: int, coordinates: List[List[int]]) -> List[int]:
        from collections import defaultdict

        block_count = defaultdict(int)

        for x, y in coordinates:
            # A black cell at (x, y) can belong to up to 4 blocks
            # Block with top-left at (x-1, y-1)
            if x > 0 and y > 0:
                block_count[(x - 1, y - 1)] += 1
            # Block with top-left at (x-1, y)
            if x > 0 and y < n - 1:
                block_count[(x - 1, y)] += 1
            # Block with top-left at (x, y-1)
            if x < m - 1 and y > 0:
                block_count[(x, y - 1)] += 1
            # Block with top-left at (x, y)
            if x < m - 1 and y < n - 1:
                block_count[(x, y)] += 1

        arr = [0] * 5
        total_blocks = (m - 1) * (n - 1)

        # Count blocks with 1, 2, 3, or 4 black cells
        for count in block_count.values():
            arr[count] += 1

        # Blocks with 0 black cells = total blocks - blocks with >= 1 black cell
        arr[0] = total_blocks - len(block_count)

        return arr

