class Solution:
    def heightOfTree(self, root: Optional[TreeNode]) -> int:
        from collections import deque

        if not root:
            return 0

        queue = deque([(root, 0)])
        max_height = 0

        while queue:
            node, depth = queue.popleft()
            max_height = max(max_height, depth)

            # If both children are None, this is a leaf.
            # Its special children are other leaves (forming a cycle),
            # so we don't traverse further from here.
            if node.left is None and node.right is None:
                continue

            if node.left:
                queue.append((node.left, depth + 1))
            if node.right:
                queue.append((node.right, depth + 1))

        return max_height

class Solution:
    def minimumIndex(self, nums: List[int]) -> int:
        # Step 1: Find the dominant element using Boyer-Moore Voting Algorithm
        candidate = None
        count = 0
        for num in nums:
            if count == 0:
                candidate = num
                count = 1
            elif num == candidate:
                count += 1
            else:
                count -= 1

        d = candidate

        # Step 2: Count total occurrences of the dominant element
        total_d = nums.count(d)
        n = len(nums)

        # Step 3: Find the minimum valid split index
        left_d = 0
        for i in range(n - 1):
            if nums[i] == d:
                left_d += 1

            left_len = i + 1
            right_len = n - i - 1
            right_d = total_d - left_d

            # Check if d is dominant in both left and right subarrays
            if left_d * 2 > left_len and right_d * 2 > right_len:
                return i

        return -1

# Definition for a category handler.
# class CategoryHandler:
#     def haveSameCategory(self, a: int, b: int) -> bool:
#         pass
class Solution:
    def numberOfCategories(self, n: int, categoryHandler: Optional['CategoryHandler']) -> int:
        representatives = []

        for i in range(n):
            # Check if the current element belongs to any of the already found categories
            is_new_category = True
            for rep in representatives:
                if categoryHandler.haveSameCategory(i, rep):
                    is_new_category = False
                    break

            # If it doesn't match any existing category, it's a new unique category
            if is_new_category:
                representatives.append(i)

        return len(representatives)

class Solution:
    def isGood(self, nums: List[int]) -> bool:
        n = max(nums)

        # base[n] has exactly n + 1 elements
        if len(nums) != n + 1:
            return False

        from collections import Counter
        counts = Counter(nums)

        # Numbers 1 to n-1 must appear exactly once
        for i in range(1, n):
            if counts[i] != 1:
                return False

        # Number n must appear exactly twice
        if counts[n] != 2:
            return False

        return True

class Solution:
    def maxScore(self, nums: List[int], x: int) -> int:
        if nums[0] % 2 == 0:
            even_score = nums[0]
            odd_score = float('-inf')
        else:
            odd_score = nums[0]
            even_score = float('-inf')

        for i in range(1, len(nums)):
            if nums[i] % 2 == 0:
                # Can skip (keep even_score), or visit from best even or best odd path
                even_score = max(even_score, max(even_score, odd_score - x) + nums[i])
            else:
                # Can skip (keep odd_score), or visit from best odd or best even path
                odd_score = max(odd_score, max(odd_score, even_score - x) + nums[i])

        return max(even_score, odd_score)

class Solution:
    def numberOfWays(self, n: int, x: int) -> int:
        MOD = 10**9 + 7
        dp = [0] * (n + 1)
        dp[0] = 1

        i = 1
        while (power := i ** x) <= n:
            for j in range(n, power - 1, -1):
                dp[j] = (dp[j] + dp[j - power]) % MOD
            i += 1

        return dp[n]

