        max_val = current_sum

        for i in range(len(nums) - 2, -1, -1):
            if nums[i] <= current_sum:
                current_sum += nums[i]
            else:
                current_sum = nums[i]

            if current_sum > max_val:
                max_val = current_sum

        return max_val

