class Solution:
    def countPalindromePaths(self, parent: List[int], s: str) -> int:
        n = len(parent)
        children = defaultdict(list)
        for i in range(1, n):
            children[parent[i]].append(i)

        # Compute bitmask for path from root to each node
        mask = [0] * n
        queue = deque([0])
        while queue:
            u = queue.popleft()
            for v in children[u]:
                mask[v] = mask[u] ^ (1 << (ord(s[v]) - ord('a')))
                queue.append(v)

        # Count frequency of each mask
        freq = defaultdict(int)
        for m in mask:
            freq[m] += 1

        ans = 0
        for m, count in freq.items():
            # Pairs with identical masks (XOR = 0, all even frequencies)
            ans += count * (count - 1) // 2
            # Pairs differing by exactly 1 bit (one odd frequency)
            for k in range(26):
                m2 = m ^ (1 << k)
                if m2 > m and m2 in freq:
                    ans += count * freq[m2]

        return ans

class Solution:
    def minimumString(self, a: str, b: str, c: str) -> str:
        def merge(s1, s2):
            # If one string is already a substring of the other
            if s2 in s1:
                return s1
            if s1 in s2:
                return s2
            # Find maximum suffix of s1 that matches prefix of s2
            max_overlap = 0
            for i in range(1, min(len(s1), len(s2)) + 1):
                if s1[-i:] == s2[:i]:
                    max_overlap = i
            return s1 + s2[max_overlap:]

        from itertools import permutations

        best = None
        for p in permutations([a, b, c]):
            result = merge(merge(p[0], p[1]), p[2])
            if best is None or len(result) < len(best) or (len(result) == len(best) and result < best):
                best = result

        return best

class Solution:
    def countSteppingNumbers(self, low: str, high: str) -> int:
        MOD = 10**9 + 7

        def count(s):
            n = len(s)
            # memo[pos][last_digit][tight][started]
            # last_digit: 0-9, or 10 for "not started"
            memo = [[[[ -1 for _ in range(2)] for _ in range(2)] for _ in range(11)] for _ in range(n)]

            def dp(pos, last_digit, tight, started):
                if pos == n:
                    return 1 if started else 0

                if memo[pos][last_digit][tight][started] != -1:
                    return memo[pos][last_digit][tight][started]

                limit = int(s[pos]) if tight else 9
                res = 0

                if not started:
                    # Place 0 (continue not started - effectively shorter number)
                    new_tight = 1 if (tight and 0 == limit) else 0
                    res = (res + dp(pos + 1, 10, new_tight, 0)) % MOD
                    # Place d from 1 to limit (start the number)
                    for d in range(1, limit + 1):
                        new_tight = 1 if (tight and d == limit) else 0
                        res = (res + dp(pos + 1, d, new_tight, 1)) % MOD
                else:
                    # Place d such that |d - last_digit| == 1
                    for d in range(max(0, last_digit - 1), min(9, last_digit + 1) + 1):
                        if d <= limit:
                            new_tight = 1 if (tight and d == limit) else 0
                            res = (res + dp(pos + 1, d, new_tight, 1)) % MOD

                memo[pos][last_digit][tight][started] = res
                return res

            return dp(0, 10, 1, 0)

        def subtract_one(s):
            digits = list(s)
            i = len(digits) - 1
            while i >= 0 and digits[i] == '0':
                digits[i] = '9'
                i -= 1
            digits[i] = str(int(digits[i]) - 1)
            result = ''.join(digits).lstrip('0')
            return result if result else "0"

        low_minus_1 = subtract_one(low)
        ans = (count(high) - count(low_minus_1)) % MOD
        return ans

class Solution:
    def kthLuckyNumber(self, k: int) -> str:
        # The sequence of lucky numbers corresponds to the binary representations 
        # of integers starting from 2, if we drop the leading '1' and map '0' to '4' and '1' to '7'.
        # For example:
        # k = 1 -> k + 1 = 2 -> binary '10' -> drop leading '1' -> '0' -> '4'
        # k = 2 -> k + 1 = 3 -> binary '11' -> drop leading '1' -> '1' -> '7'
        # k = 3 -> k + 1 = 4 -> binary '100' -> drop leading '1' -> '00' -> '44'

        binary_str = bin(k + 1)[3:]  # [3:] removes the '0b1' prefix
        return binary_str.replace('0', '4').replace('1', '7')

