from typing import List

class Solution:
    def minimumSeconds(self, nums: List[int]) -> int:
        n = len(nums)
        positions = defaultdict(list)
        for i, num in enumerate(nums):
            positions[num].append(i)

        min_time = float('inf')
        for num, pos in positions.items():
            max_dist = 0
            m = len(pos)
            for i in range(m):
                if i == m - 1:
                    # Wrap-around gap: from last occurrence to first occurrence
                    dist = pos[0] + n - pos[i]
                else:
                    dist = pos[i + 1] - pos[i]
                max_dist = max(max_dist, dist)
            time = max_dist // 2
            min_time = min(min_time, time)

        return min_time

class Solution:
    def minimumTime(self, nums1: List[int], nums2: List[int], x: int) -> int:
        n = len(nums1)
        S1 = sum(nums1)
        S2 = sum(nums2)

        # Sort by nums2 to apply rearrangement inequality
        pairs = sorted(zip(nums1, nums2), key=lambda p: p[1])

        # dp[j] = maximum reduction achievable using exactly j operations
        dp = [0] * (n + 1)

        for i in range(n):
            a, b = pairs[i]
            # Iterate backwards to avoid using the same element twice
            for j in range(i + 1, 0, -1):
                dp[j] = max(dp[j], dp[j - 1] + a + j * b)

        # Check each possible time t from 0 to n
        for t in range(n + 1):
            if S1 + t * S2 - dp[t] <= x:
                return t

        return -1

