class Solution:
    def minimumSeconds(self, land: List[List[str]]) -> int:
        n = len(land)
        m = len(land[0])

        start = None
        dest = None
        flood_queue = deque()

        flood_time = [[float('inf')] * m for _ in range(n)]

        for r in range(n):
            for c in range(m):
                if land[r][c] == 'S':
                    start = (r, c)
                elif land[r][c] == 'D':
                    dest = (r, c)
                elif land[r][c] == '*':
                    flood_time[r][c] = 0
                    flood_queue.append((r, c))

        directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

        # Multi-source BFS for flood spread
        while flood_queue:
            r, c = flood_queue.popleft()
            t = flood_time[r][c]
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m:
                    if land[nr][nc] in ('.', 'S') and flood_time[nr][nc] == float('inf'):
                        flood_time[nr][nc] = t + 1
                        flood_queue.append((nr, nc))

        # BFS for person's shortest path
        dist = [[float('inf')] * m for _ in range(n)]
        dist[start[0]][start[1]] = 0
        person_queue = deque()
        person_queue.append((start[0], start[1], 0))

        while person_queue:
            r, c, t = person_queue.popleft()

            if (r, c) == dest:
                return t

            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m:
                    if land[nr][nc] != 'X' and dist[nr][nc] == float('inf'):
                        # Can only step on cell if it's not flooded at arrival time
                        if flood_time[nr][nc] > t + 1:
                            dist[nr][nc] = t + 1
                            person_queue.append((nr, nc, t + 1))

        return -1

class Solution:
    def canMakeSubsequence(self, str1: str, str2: str) -> bool:
