        while i < n and j < m:
            # Check if characters match directly or cyclically (str1[i] + 1 == str2[j])
            if str1[i] == str2[j] or (ord(str1[i]) - 97 + 1) % 26 == ord(str2[j]) - 97:
                j += 1
            i += 1

        return j == m

class Solution:
    def minimumOperations(self, nums: List[int]) -> int:
        # dp[i] represents the length of the longest non-decreasing 
        # subsequence that ends with value i (i = 1, 2, 3)
        dp = [0, 0, 0, 0]  # 1-indexed for convenience

        for num in nums:
            if num == 1:
                # Can only extend subsequences ending with 1
                dp[1] += 1
            elif num == 2:
                # Can extend subsequences ending with 1 or 2
                dp[2] = max(dp[1], dp[2]) + 1
            elif num == 3:
                # Can extend subsequences ending with 1, 2, or 3
                dp[3] = max(dp[1], dp[2], dp[3]) + 1

        # The longest non-decreasing subsequence length
        longest = max(dp[1], dp[2], dp[3])

        # Minimum removals = total length - longest non-decreasing subsequence
        return len(nums) - longest

class Solution:
    def numberOfBeautifulIntegers(self, low: int, high: int, k: int) -> int:
        from functools import lru_cache

        def count(n):
            if n <= 0:
                return 0
            s = str(n)
            length = len(s)

            @lru_cache(None)
            def dp(pos, tight, started, diff, mod):
                if pos == length:
                    return 1 if (started and diff == 0 and mod == 0) else 0

                limit = int(s[pos]) if tight else 9
                res = 0

                for d in range(limit + 1):
                    new_tight = tight and (d == limit)
                    new_started = started or (d > 0)

                    if not new_started:
                        # Leading zero, doesn't count as a digit
                        new_diff = diff
                    elif d % 2 == 0:
                        new_diff = diff + 1
                    else:
                        new_diff = diff - 1

                    new_mod = (mod * 10 + d) % k
                    res += dp(pos + 1, new_tight, new_started, new_diff, new_mod)

                return res

            return dp(0, True, False, 0, 0)

        return count(high) - count(low - 1)

class Solution:
    def minimumSum(self, n: int, k: int) -> int:
        m = k // 2
        if n <= m:
            return n * (n + 1) // 2
        else:
            sum1 = m * (m + 1) // 2
            rem = n - m
            sum2 = rem * k + rem * (rem - 1) // 2
            return sum1 + sum2

