class Solution:
    def longestEqualSubarray(self, nums: List[int], k: int) -> int:
        n = len(nums)
        # Since 1 <= nums[i] <= nums.length, we can use an array of lists 
        # to group the indices of each number.
        indices = [[] for _ in range(n + 1)]
        for i, num in enumerate(nums):
            indices[num].append(i)

        max_len = 0

        # For each unique number, find the longest subarray of this number 
        # such that the number of elements to delete is at most k.
        for idx_list in indices:
            if not idx_list:
                continue

            l = 0
            for r in range(len(idx_list)):
                # The number of elements to delete between idx_list[l] and idx_list[r]
                # is the total distance minus the number of target elements in this range.
                while idx_list[r] - idx_list[l] - (r - l) > k:
                    l += 1

                # Update the maximum length found so far
                current_len = r - l + 1
                if current_len > max_len:
                    max_len = current_len

        return max_len

