class Solution:
    def minOperations(self, nums: List[int], target: int) -> int:
        count = [0] * 32
        for num in nums:
            count[num.bit_length() - 1] += 1

        operations = 0
        for i in range(31):
            if (target >> i) & 1:
                if count[i] > 0:
                    count[i] -= 1
                else:
                    # Find the smallest available larger power of 2
                    j = i + 1
                    while j < 31 and count[j] == 0:
                        j += 1
                    if j == 31:
                        return -1
                    # Split 2^j down to 2^i
                    operations += j - i
                    count[j] -= 1
                    # The split produces one of each 2^k for k in [i+1, j-1]
                    # and one 2^i which we immediately use (net 0 for count[i])
                    for k in range(i + 1, j):
                        count[k] += 1
            # Two 2^i can combine to form one 2^(i+1) for summing purposes
            count[i + 1] += count[i] // 2

        return operations

