class Solution:
    def minimumOperations(self, num: str) -> int:
        n = len(num)
        ans = n  # Maximum possible operations is deleting all digits (resulting in 0)

        # Case where the resulting number is just "0"
        if '0' in num:
            ans = min(ans, n - 1)

        # Cases where the resulting number ends with "00", "25", "50", or "75"
        for X, Y in ["00", "25", "50", "75"]:
            i = num.rfind(Y)
            if i != -1:
                j = num.rfind(X, 0, i)
                if j != -1:
                    # The number of deletions is the total length minus the 2 kept digits,
                    # minus the number of digits before the first kept digit (which is j).
                    ans = min(ans, n - 2 - j)

        return ans

