class Solution:
    def minOperationsQueries(self, n: int, edges: List[List[int]], queries: List[List[int]]) -> List[int]:
        adj = [[] for _ in range(n)]
        for u, v, w in edges:
            adj[u].append((v, w))
            adj[v].append((u, w))

        LOG = 15  # 2^14 = 16384 > 10^4
        depth = [0] * n
        up = [[0] * LOG for _ in range(n)]
        count = [[0] * 27 for _ in range(n)]  # weights 1..26

        # BFS to build tree structure from root 0
        visited = [False] * n
        visited[0] = True
        queue = [0]

        while queue:
            next_queue = []
            for u in queue:
                for v, w in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        depth[v] = depth[u] + 1
                        up[v][0] = u
                        # Build binary lifting table
                        for j in range(1, LOG):
                            up[v][j] = up[up[v][j - 1]][j - 1]
                        # Copy prefix weight counts from parent
                        for i in range(1, 27):
                            count[v][i] = count[u][i]
                        count[v][w] += 1
                        next_queue.append(v)
            queue = next_queue

        def lca(u, v):
            if depth[u] < depth[v]:
                u, v = v, u
            # Lift u to same depth as v
            diff = depth[u] - depth[v]
            for j in range(LOG):
                if (diff >> j) & 1:
                    u = up[u][j]
            if u == v:
                return u
            # Lift both until they meet
            for j in range(LOG - 1, -1, -1):
                if up[u][j] != up[v][j]:
                    u = up[u][j]
                    v = up[v][j]
            return up[u][0]

        ans = []
        for a, b in queries:
            l = lca(a, b)
            path_len = depth[a] + depth[b] - 2 * depth[l]
            max_freq = 0
            for i in range(1, 27):
                freq = count[a][i] + count[b][i] - 2 * count[l][i]
                if freq > max_freq:
                    max_freq = freq
            ans.append(path_len - max_freq)

        return ans

class Solution:
    def smallestNumber(self, n: int) -> str:
        if n == 1:
            return "1"

        digits = []
        # Greedily divide by largest single-digit factors first
        # This minimizes the total number of digits needed
        for d in range(9, 1, -1):
            while n % d == 0:
                digits.append(d)
                n //= d

        # If n > 1, it has a prime factor > 7, impossible to represent
        if n > 1:
            return "-1"

        # Sort digits in ascending order to form the smallest number
        digits.sort()
        return "".join(map(str, digits))

