class Solution:
    def minimumMoves(self, grid: List[List[int]]) -> int:
        sources = []  # positions of excess stones
        targets = []  # positions of empty cells

        for i in range(3):
            for j in range(3):
                if grid[i][j] > 1:
                    for _ in range(grid[i][j] - 1):
                        sources.append((i, j))
                elif grid[i][j] == 0:
                    targets.append((i, j))

        # If no moves needed
        if not sources:
            return 0

        min_moves = float('inf')

        # Try all permutations of assigning excess stones to empty cells
        for perm in permutations(targets):
            moves = 0
            for k in range(len(sources)):
                moves += abs(sources[k][0] - perm[k][0]) + abs(sources[k][1] - perm[k][1])
            min_moves = min(min_moves, moves)

        return min_moves

class Solution:
    def sumRemoteness(self, grid: List[List[int]]) -> int:
        from collections import deque

        n = len(grid)
        visited = [[False] * n for _ in range(n)]

        total_sum = 0
        for i in range(n):
            for j in range(n):
                if grid[i][j] != -1:
                    total_sum += grid[i][j]

        components = []

        for i in range(n):
            for j in range(n):
                if grid[i][j] != -1 and not visited[i][j]:
                    queue = deque([(i, j)])
                    visited[i][j] = True
                    comp_sum = 0
                    comp_size = 0

                    while queue:
                        x, y = queue.popleft()
                        comp_sum += grid[x][y]
                        comp_size += 1

                        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                            nx, ny = x + dx, y + dy
                            if 0 <= nx < n and 0 <= ny < n and not visited[nx][ny] and grid[nx][ny] != -1:
                                visited[nx][ny] = True
                                queue.append((nx, ny))

                    components.append((comp_size, comp_sum))

        result = 0
        for comp_size, comp_sum in components:
            result += comp_size * (total_sum - comp_sum)

        return result

