class Solution:
    def minimumRightShifts(self, nums: List[int]) -> int:
        n = len(nums)
        drops = 0
        drop_index = -1

        # Count the number of times an element is greater than the next element
        for i in range(n - 1):
            if nums[i] > nums[i+1]:
                drops += 1
                drop_index = i

        # If there are no drops, the array is already sorted
        if drops == 0:
            return 0
        # If there is exactly one drop, we must ensure the last element is less than the first
        # to form a completely sorted array when wrapped around
        elif drops == 1:
            if nums[-1] < nums[0]:
                return n - 1 - drop_index
            else:
                return -1
        # If there is more than one drop, it's impossible to sort with right shifts
        else:
            return -1

class Solution:
    def minLengthAfterRemovals(self, nums: List[int]) -> int:
        n = len(nums)
        mid = n // 2
        i = 0
        j = mid
        pairs = 0

        while i < mid and j < n:
            if nums[i] < nums[j]:
                pairs += 1
                i += 1
                j += 1
            else:
                j += 1

        return n - 2 * pairs

class Solution:
    def countWays(self, nums: List[int]) -> int:
        nums.sort()
        n = len(nums)
        count = 0

        # k = 0: no students selected, all must have nums[i] > 0
        if nums[0] > 0:
            count += 1

        # k = 1 to n-1: first k selected, rest not selected
        for k in range(1, n):
            if nums[k - 1] < k and nums[k] > k:
                count += 1

        # k = n: all students selected, all must have nums[i] < n
        if nums[n - 1] < n:
            count += 1

        return count

