class Solution:
    def maxNumberOfAlloys(self, n: int, k: int, budget: int, composition: List[List[int]], stock: List[int], cost: List[int]) -> int:
        max_alloys = 0

        # Iterate over each machine to find the maximum alloys it can produce
        for i in range(k):
            left, right = 0, 2 * 10**8 + 1
            best_for_machine = 0

            # Binary search for the maximum number of alloys for the current machine
            while left <= right:
                mid = (left + right) // 2
                current_cost = 0
                possible = True

                # Calculate the cost to create 'mid' alloys using machine 'i'
                for j in range(n):
                    needed = mid * composition[i][j]
                    if needed > stock[j]:
                        current_cost += (needed - stock[j]) * cost[j]

                    # Early exit if the cost exceeds the budget
                    if current_cost > budget:
                        possible = False
                        break

                if possible:
                    best_for_machine = mid
                    left = mid + 1  # Try to create more alloys
                else:
                    right = mid - 1  # Need to create fewer alloys

            # Update the global maximum alloys across all machines
            if best_for_machine > max_alloys:
                max_alloys = best_for_machine

        return max_alloys

class Solution:
    def maximumSum(self, nums: List[int]) -> int:
        n = len(nums)

        def square_free_part(x):
            d = 2
            while d * d <= x:
                while x % (d * d) == 0:
                    x //= (d * d)
                d += 1
            return x

        from collections import defaultdict
        groups = defaultdict(int)

        for i in range(1, n + 1):
            sfp = square_free_part(i)
            groups[sfp] += nums[i - 1]

        return max(groups.values())

