class Solution:
    def maximumSumOfHeights(self, maxHeights: List[int]) -> int:
        n = len(maxHeights)

        # Compute prefix sums using monotonic stack
        prefix = [0] * n
        stack = []  # stores indices with strictly increasing maxHeights values
        for i in range(n):
            while stack and maxHeights[stack[-1]] >= maxHeights[i]:
                stack.pop()
            if stack:
                j = stack[-1]
                prefix[i] = prefix[j] + (i - j) * maxHeights[i]
            else:
                prefix[i] = (i + 1) * maxHeights[i]
            stack.append(i)

        # Compute suffix sums using monotonic stack
        suffix = [0] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and maxHeights[stack[-1]] >= maxHeights[i]:
                stack.pop()
            if stack:
                j = stack[-1]
                suffix[i] = suffix[j] + (j - i) * maxHeights[i]
            else:
                suffix[i] = (n - i) * maxHeights[i]
            stack.append(i)

        # Find the maximum total sum across all possible peak positions
        ans = 0
        for i in range(n):
            ans = max(ans, prefix[i] + suffix[i] - maxHeights[i])

        return ans

