class Solution:
    def countPaths(self, n: int, edges: List[List[int]]) -> int:
        # Sieve of Eratosthenes to find all prime numbers up to n
        is_prime = [True] * (n + 1)
        if n >= 0:
            is_prime[0] = False
        if n >= 1:
            is_prime[1] = False

        for i in range(2, int(n**0.5) + 1):
            if is_prime[i]:
                for j in range(i * i, n + 1, i):
                    is_prime[j] = False

        # Build adjacency list for the tree
        adj = [[] for _ in range(n + 1)]
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        # Find connected components of non-prime nodes
        comp_id = [-1] * (n + 1)
        comp_size = []
        curr_id = 0

        for i in range(1, n + 1):
            if not is_prime[i] and comp_id[i] == -1:
                q = [i]
                comp_id[i] = curr_id
                size = 0
                head = 0
                # BFS to find the size of the current component
                while head < len(q):
                    node = q[head]
                    head += 1
                    size += 1
                    for neighbor in adj[node]:
                        if not is_prime[neighbor] and comp_id[neighbor] == -1:
                            comp_id[neighbor] = curr_id
                            q.append(neighbor)
                comp_size.append(size)
                curr_id += 1

        ans = 0
        # For each prime node, calculate the number of valid paths passing through it
        for p in range(1, n + 1):
            if is_prime[p]:
                S = 0
                sum_sq = 0
                for neighbor in adj[p]:
                    if not is_prime[neighbor]:
                        c_id = comp_id[neighbor]
                        size = comp_size[c_id]
                        S += size
                        sum_sq += size * size
                # S paths where the prime node is one endpoint
                # (S^2 - sum_sq) // 2 paths where the prime node is strictly in the middle
                ans += S + (S * S - sum_sq) // 2

        return ans

