class Solution:
    def canAliceWin(self, a: List[str], b: List[str]) -> bool:
        last_word = a[0]
        i, j = 1, 0
        while True:
            # Bob's turn
            while j < len(b) and b[j] <= last_word:
                j += 1
            if j == len(b) or b[j][0] > chr(ord(last_word[0]) + 1):
                return True  # Bob can't play, Alice wins
            last_word = b[j]
            j += 1

            # Alice's turn
            while i < len(a) and a[i] <= last_word:
                i += 1
            if i == len(a) or a[i][0] > chr(ord(last_word[0]) + 1):
                return False  # Alice can't play, Bob wins
            last_word = a[i]
            i += 1

