class Solution:
    def maxSubarrays(self, nums: List[int]) -> int:
        total_and = nums[0]
        for num in nums[1:]:
            total_and &= num

        if total_and > 0:
            return 1

        count = 0
        current_and = -1  # -1 is all 1s in binary, acts as identity for AND
        for num in nums:
            current_and &= num
            if current_and == 0:
                count += 1
                current_and = -1  # reset for next subarray

