                current_product *= nums[i]
            else:
                groups += 1
                current_product = nums[i]

        return groups

class Solution:
    def minOperations(self, s1: str, s2: str, x: int) -> int:
        n = len(s1)
        diff = []
        for i in range(n):
            if s1[i] != s2[i]:
                diff.append(i)

        m = len(diff)
        if m % 2 == 1:
            return -1
        if m == 0:
            return 0

        # dp[i] = max saving using the first i mismatched positions
        dp = [0] * (m + 1)
        for i in range(2, m + 1):
            saving = max(0, x - (diff[i - 1] - diff[i - 2]))
            dp[i] = max(dp[i - 1], dp[i - 2] + saving)

        return m // 2 * x - dp[m]

