class Solution:
    def maxSum(self, nums: List[int], k: int) -> int:
        # Count the number of 1s at each bit position across all numbers
        count = [0] * 30
        for num in nums:
            for b in range(30):
                if (num >> b) & 1:
                    count[b] += 1

        ans = 0
        MOD = 10**9 + 7

        # Greedily form the k largest possible numbers
        for _ in range(k):
            val = 0
            for b in range(30):
                if count[b]:
                    val |= (1 << b)
                    count[b] -= 1
            ans = (ans + val * val) % MOD

        return ans

