        n = len(nums)
        min_idx = 0
        max_idx = 0

        for j in range(indexDifference, n):
            i = j - indexDifference

            # Update the indices of the minimum and maximum values in the valid prefix
            if nums[i] < nums[min_idx]:
                min_idx = i
            if nums[i] > nums[max_idx]:
                max_idx = i

            # Check if the current element and the min/max in the valid prefix satisfy the valueDifference condition
            if nums[j] - nums[min_idx] >= valueDifference:
                return [min_idx, j]
            if nums[max_idx] - nums[j] >= valueDifference:
                return [max_idx, j]

        return [-1, -1]

class Solution:
    def minimumChanges(self, s: str, k: int) -> int:
        n = len(s)

        # Precompute divisors for each length
        divisors = [[] for _ in range(n + 1)]
        for L in range(2, n + 1):
            for d in range(1, L):
                if L % d == 0:
                    divisors[L].append(d)

        # Precompute cost[i][j] = minimum changes to make s[i..j] a semi-palindrome
        INF = 10**9
        cost = [[INF] * n for _ in range(n)]

        for i in range(n):
            for j in range(i + 1, n):
                L = j - i + 1
                min_cost = INF

                for d in divisors[L]:
                    total_cost = 0
                    k_groups = L // d
                    half = k_groups // 2
                    for r in range(d):
                        base = i + r
                        for a in range(half):
                            if s[base + a * d] != s[base + (k_groups - 1 - a) * d]:
                                total_cost += 1
                    if total_cost < min_cost:
                        min_cost = total_cost

                cost[i][j] = min_cost

        # DP: dp[i][j] = min cost to partition s[0..i-1] into j parts
        dp = [[INF] * (k + 1) for _ in range(n + 1)]
        dp[0][0] = 0

        for i in range(2, n + 1):
            for j in range(1, min(k, i // 2) + 1):
                for m in range(2 * (j - 1), i - 1):
                    c = cost[m][i - 1]
                    if c < INF and dp[m][j - 1] < INF:
                        val = dp[m][j - 1] + c
                        if val < dp[i][j]:
                            dp[i][j] = val

        return dp[n][k]

