class Solution:
    def distributeCandies(self, n: int, limit: int) -> int:
        def f(k: int) -> int:
            if k < 0:
                return 0
            return (k + 1) * (k + 2) // 2

        # Principle of Inclusion-Exclusion
        ans = f(n)
        ans -= 3 * f(n - limit - 1)
        ans += 3 * f(n - 2 * limit - 2)
        ans -= f(n - 3 * limit - 3)

        return ans

