class Solution:
    def minOperations(self, nums1: List[int], nums2: List[int]) -> int:
        n = len(nums1)

        def check(x: int, y: int, initial_swaps: int) -> int:
            swaps = initial_swaps
            for i in range(n - 1):
                a, b = nums1[i], nums2[i]
                can_keep = (a <= x and b <= y)
                can_swap = (b <= x and a <= y)

                if not can_keep and not can_swap:
                    return float('inf')
                elif not can_keep and can_swap:
                    swaps += 1
            return swaps

        # Case 1: Do not swap the last elements
        ans1 = check(nums1[-1], nums2[-1], 0)

        # Case 2: Swap the last elements
        ans2 = check(nums2[-1], nums1[-1], 1)

        ans = min(ans1, ans2)
        return ans if ans != float('inf') else -1

class Solution:
    def maximumStrongPairXor(self, nums: List[int]) -> int:
        nums.sort()
        n = len(nums)

        MAX = n * 20 + 2
        ch0 = [0] * MAX
        ch1 = [0] * MAX
        cnt = [0] * MAX
        sz = 1

        ans = 0
        i = 0
        for j in range(n):
            x = nums[j]

            # insert x into trie
            u = 0
            for bit in range(19, -1, -1):
                if (x >> bit) & 1:
                    v = ch1[u]
                    if not v:
                        v = sz
                        ch1[u] = v
                        sz += 1
                    u = v
                else:
                    v = ch0[u]
                    if not v:
                        v = sz
                        ch0[u] = v
                        sz += 1
                    u = v
                cnt[u] += 1

            # remove elements that violate 2 * nums[i] >= nums[j]
            while 2 * nums[i] < x:
                y = nums[i]
                u = 0
                for bit in range(19, -1, -1):
                    if (y >> bit) & 1:
                        u = ch1[u]
                    else:
                        u = ch0[u]
                    cnt[u] -= 1
                i += 1

            # query max XOR with x
            u = 0
            res = 0
            for bit in range(19, -1, -1):
                if (x >> bit) & 1:
                    c = ch0[u]
                    if c and cnt[c]:
                        res |= (1 << bit)
                        u = c
                    else:
                        u = ch1[u]
                else:
                    c = ch1[u]
                    if c and cnt[c]:
                        res |= (1 << bit)
                        u = c
                    else:
                        u = ch0[u]

            if res > ans:
                ans = res

        return ans

