class Solution:
    def leftmostBuildingQueries(self, heights: List[int], queries: List[List[int]]) -> List[int]:
        n = len(heights)
        m = len(queries)
        ans = [-1] * m

        # Group queries by their start index
        query_groups = [[] for _ in range(n)]

        for i, (a, b) in enumerate(queries):
            if a == b:
                ans[i] = a
            elif a < b:
                if heights[a] < heights[b]:
                    ans[i] = b
                else:
                    # Need smallest k > b with heights[k] > heights[a]
                    query_groups[b].append((heights[a], i))
            else:  # a > b
                if heights[b] < heights[a]:
                    ans[i] = a
                else:
                    # Need smallest k > a with heights[k] > heights[b]
                    query_groups[a].append((heights[b], i))

        # Monotonic stack: indices with heights decreasing from bottom to top
        stack = []

        for i in range(n - 1, -1, -1):
            # Answer all queries that need to search past index i
            for target, qi in query_groups[i]:
                lo, hi = 0, len(stack) - 1
                res = -1
                # Binary search for topmost element with height > target
                while lo <= hi:
                    mid = (lo + hi) // 2
                    if heights[stack[mid]] > target:
                        res = mid
                        lo = mid + 1
                    else:
                        hi = mid - 1
                if res != -1:
                    ans[qi] = stack[res]

            # Maintain monotonic stack
            while stack and heights[stack[-1]] <= heights[i]:
                stack.pop()
            stack.append(i)

        return ans

