class Solution:
    def maxGcdSum(self, nums: List[int], k: int) -> int:
        n = len(nums)
        prefix_sum = [0] * (n + 1)
        for i in range(n):
            prefix_sum[i+1] = prefix_sum[i] + nums[i]

        ans = 0
        current_states = []

        for j in range(n):
            num = nums[j]
            next_states = [(num, j)]
            for g, start in current_states:
                next_states.append((math.gcd(g, num), start))

            current_states_dict = {}
            for g, start in next_states:
                if g not in current_states_dict or start < current_states_dict[g]:
                    current_states_dict[g] = start

            current_states = list(current_states_dict.items())

            for g, start in current_states:
                if j - start + 1 >= k:
                    subarray_sum = prefix_sum[j+1] - prefix_sum[start]
                    val = g * subarray_sum
                    if val > ans:
                        ans = val

        return ans

