            bars.sort()
            max_cons = 1
            curr_cons = 1
            for i in range(1, len(bars)):
                if bars[i] == bars[i-1] + 1:
                    curr_cons += 1
                else:
                    curr_cons = 1
                if curr_cons > max_cons:
                    max_cons = curr_cons
            return max_cons

        max_h = get_max_consecutive(hBars)
        max_v = get_max_consecutive(vBars)

        side = min(max_h + 1, max_v + 1)
