    def minimumCoins(self, prices: List[int]) -> int:
        n = len(prices)
        # dp[i] = min cost to get all fruits from index i to n-1, buying fruit i
        dp = [0] * (n + 1)

        for i in range(n - 1, -1, -1):
            min_next = float('inf')
            # After buying fruit i, fruits i+1 to 2i+1 are free.
            # We can next buy any fruit j from i+1 to 2i+2.
            for j in range(i + 1, min(2 * i + 3, n + 1)):
                if dp[j] < min_next:
                    min_next = dp[j]
            dp[i] = prices[i] + min_next

        return dp[0]

