class Solution:
    def areSimilar(self, mat: List[List[int]], k: int) -> bool:
        m = len(mat)
        n = len(mat[0])
        shift = k % n

        for i in range(m):
            if i % 2 == 0:
                # Even-indexed row: shifted left by k
                # After left shift by `shift`, position j gets value from (j + shift) % n
                for j in range(n):
                    if mat[i][j] != mat[i][(j + shift) % n]:
                        return False
            else:
                # Odd-indexed row: shifted right by k
                # After right shift by `shift`, position j gets value from (j - shift) % n
                for j in range(n):
                    if mat[i][j] != mat[i][(j - shift) % n]:
                        return False

        return True

