class Solution:
    def numberOfSets(self, n: int, maxDistance: int, roads: List[List[int]]) -> int:
        # Initialize adjacency matrix with a large value (10**9)
        adj = [[10**9] * n for _ in range(n)]
        for i in range(n):
            adj[i][i] = 0

        # Populate the adjacency matrix with the minimum weight for multiple roads
        for u, v, w in roads:
            if w < adj[u][v]:
                adj[u][v] = w
                adj[v][u] = w

        ans = 0

        # Iterate over all possible subsets of branches using a bitmask
        for mask in range(1 << n):
            active = [i for i in range(n) if (mask & (1 << i))]

            # If 0 or 1 branch is active, the condition is trivially satisfied
            if len(active) <= 1:
                ans += 1
                continue

            # Initialize distance matrix for the current subset
            dist = [[10**9] * n for _ in range(n)]
            for i in active:
                dist[i][i] = 0
                for j in active:
                    if i != j:
                        dist[i][j] = adj[i][j]

            # Floyd-Warshall algorithm to find all-pairs shortest paths
            for k in active:
                dk = dist[k]
                for i in active:
                    di = dist[i]
                    dik = di[k]
                    for j in active:
                        val = dik + dk[j]
                        if val < di[j]:
                            di[j] = val

            # Check if the maximum distance between any pair of active branches is within maxDistance
            valid = True
            for i in active:
                di = dist[i]
                for j in active:
                    if di[j] > maxDistance:
                        valid = False
                        break
                if not valid:
                    break

            if valid:
                ans += 1

        return ans

