        positions = []
        ans = 0
        for r in range(len(nums)):
            if nums[r] == max_val:
                positions.append(r)
            if len(positions) >= k:
                ans += positions[len(positions) - k] + 1
        return ans

class Solution:
    def findMissingAndRepeatedValues(self, grid: List[List[int]]) -> List[int]:
        n = len(grid)
        counts = [0] * (n * n + 1)
        a = -1

        # Find the repeated number
        for row in grid:
            for val in row:
                counts[val] += 1
                if counts[val] == 2:
                    a = val

        b = -1
        # Find the missing number
        for i in range(1, n * n + 1):
            if counts[i] == 0:
                b = i
                break

        return [a, b]

