class Solution:
    def minimumCoins(self, prices: List[int]) -> int:
        n = len(prices)
        dq = deque()  # stores (index, dp_value)
        prev_dp = 0

        for i in range(n, 0, -1):
            # Add dp[i+1] to the deque (it enters the window)
            if i + 1 <= n:
                while dq and dq[-1][1] >= prev_dp:
                    dq.pop()
                dq.append((i + 1, prev_dp))

            if 2 * i >= n:
                # All remaining fruits are free
                current_dp = prices[i - 1]
            else:
                # Remove elements that fall out of the window [i+1, 2i+1]
                while dq and dq[0][0] > 2 * i + 1:
                    dq.popleft()
                # Front of deque has the minimum dp value in the window
                current_dp = prices[i - 1] + dq[0][1]

            prev_dp = current_dp

        return prev_dp

class Solution:
    def incremovableSubarrayCount(self, nums: List[int]) -> int:
        n = len(nums)
        count = 0

        for i in range(n):
            for j in range(i, n):
                # Remove subarray nums[i..j]
                remaining = nums[:i] + nums[j+1:]

                # Check if remaining is strictly increasing
                is_increasing = True
                for k in range(1, len(remaining)):
                    if remaining[k] <= remaining[k - 1]:
                        is_increasing = False
                        break

                if is_increasing:
                    count += 1

        return count

