class Solution:
    def largestPerimeter(self, nums: List[int]) -> int:
        nums.sort()
        prefix_sum = sum(nums)

        # Iterate from the largest element down to the 3rd element
        for i in range(len(nums) - 1, 1, -1):
            # Check if the sum of the remaining smaller sides is strictly greater than the largest side
            if prefix_sum - nums[i] > nums[i]:
                return prefix_sum
            # Otherwise, remove the current largest element and check the next one
            prefix_sum -= nums[i]

        return -1

