class Solution:
    def maximizeSquareArea(self, m: int, n: int, hFences: List[int], vFences: List[int]) -> int:
        MOD = 10**9 + 7

        # Include boundary fences
        h_positions = sorted([1, m] + hFences)
        v_positions = sorted([1, n] + vFences)

        # Compute all pairwise differences for horizontal positions
        h_diffs = set()
        for i in range(len(h_positions)):
            for j in range(i + 1, len(h_positions)):
                h_diffs.add(h_positions[j] - h_positions[i])

        # Find maximum common difference with vertical positions
        max_d = -1
        for i in range(len(v_positions)):
            for j in range(i + 1, len(v_positions)):
                d = v_positions[j] - v_positions[i]
                if d in h_diffs:
                    if d > max_d:
                        max_d = d

        if max_d == -1:
            return -1

        return (max_d * max_d) % MOD

