class Solution:
    def minimumCost(self, source: str, target: str, original: List[str], changed: List[str], cost: List[int]) -> int:
        INF = float('inf')
        # Initialize the distance matrix for Floyd-Warshall algorithm
        dist = [[INF] * 26 for _ in range(26)]

        # Distance from a character to itself is 0
        for i in range(26):
            dist[i][i] = 0

        # Populate the initial edges from the given transformations
        for u, v, w in zip(original, changed, cost):
            u_idx = ord(u) - 97
            v_idx = ord(v) - 97
            if w < dist[u_idx][v_idx]:
                dist[u_idx][v_idx] = w

        # Floyd-Warshall algorithm to find all-pairs shortest paths
        for k in range(26):
            dist_k = dist[k]
            for i in range(26):
                dist_i = dist[i]
                dik = dist_i[k]
                if dik == INF:
                    continue
                for j in range(26):
                    val = dik + dist_k[j]
                    if val < dist_i[j]:
                        dist_i[j] = val

        total_cost = 0
        # Calculate the total minimum cost to convert source to target
        for u, v in zip(source, target):
            if u != v:
                u_idx = ord(u) - 97
                v_idx = ord(v) - 97
                d = dist[u_idx][v_idx]
                if d == INF:
                    return -1
                total_cost += d

        return total_cost

