from typing import List

class Solution:
    def minimumCost(self, source: str, target: str, original: List[str], changed: List[str], cost: List[int]) -> int:
        unique_strings = list(set(original + changed))
        str_to_idx = {s: i for i, s in enumerate(unique_strings)}
        num_strings = len(unique_strings)

        INF = float('inf')

        # Build adjacency list with minimum weights
        adj = [{} for _ in range(num_strings)]
        for o, c, z in zip(original, changed, cost):
            u = str_to_idx[o]
            v = str_to_idx[c]
            if v not in adj[u] or z < adj[u][v]:
                adj[u][v] = z

        adj_list = [[] for _ in range(num_strings)]
        for u in range(num_strings):
            for v, w in adj[u].items():
                adj_list[u].append((v, w))

        # Dijkstra from each node that appears in original
        orig_indices = set(str_to_idx[s] for s in set(original))
        dist = {}
        for i in orig_indices:
            dist[i] = [INF] * num_strings
            dist[i][i] = 0
            pq = [(0, i)]
            while pq:
                d, u = heapq.heappop(pq)
                if d > dist[i][u]:
                    continue
                for v, w in adj_list[u]:
                    new_d = d + w
                    if new_d < dist[i][v]:
                        dist[i][v] = new_d
                        heapq.heappush(pq, (new_d, v))

        n = len(source)
        transitions = [[] for _ in range(n)]

        # Find all valid segment transitions
        for s in set(original):
            idx = str_to_idx[s]
            L = len(s)
            start = 0
            while True:
                pos = source.find(s, start)
                if pos == -1:
                    break
                t = target[pos:pos+L]
                if t in str_to_idx:
                    t_idx = str_to_idx[t]
                    d = dist[idx][t_idx]
                    if d < INF:
                        transitions[pos].append((pos + L, d))
                start = pos + 1

        # DP to find minimum cost partition
        dp = [INF] * (n + 1)
        dp[n] = 0

        for i in range(n - 1, -1, -1):
            if source[i] == target[i]:
                dp[i] = dp[i + 1]
            for end_pos, c in transitions[i]:
                val = c + dp[end_pos]
                if val < dp[i]:
                    dp[i] = val

        return dp[0] if dp[0] < INF else -1

class Solution:
    def maximumLength(self, s: str) -> int:
        counts = {}
        n = len(s)

        # Iterate over all possible substrings
        for i in range(n):
            for j in range(i + 1, n + 1):
                sub = s[i:j]
                # Check if the substring is special (made up of only a single character)
                if sub == sub[0] * len(sub):
                    counts[sub] = counts.get(sub, 0) + 1

        max_len = -1
        # Find the maximum length among special substrings that occur at least thrice
        for sub, count in counts.items():
            if count >= 3:
                if len(sub) > max_len:
                    max_len = len(sub)

        return max_len

class Solution:
    def maximumLength(self, s: str) -> int:
        # Store the top 3 block lengths for each character
        top = [[0, 0, 0] for _ in range(26)]

        n = len(s)
        i = 0
        while i < n:
            j = i
            while j < n and s[j] == s[i]:
                j += 1
            length = j - i
            c = ord(s[i]) - ord('a')

            # Update top 3 lengths for the current character
            if length > top[c][0]:
                top[c][2] = top[c][1]
                top[c][1] = top[c][0]
                top[c][0] = length
            elif length > top[c][1]:
                top[c][2] = top[c][1]
                top[c][1] = length
            elif length > top[c][2]:
                top[c][2] = length

            i = j

        ans = -1
        for c in range(26):
            m1, m2, m3 = top[c]

            # Case 1: One block provides 3 occurrences
            if m1 - 2 >= 1:
                ans = max(ans, m1 - 2)

            # Case 2: Two blocks provide 2 + 1 = 3 occurrences
            if m2 > 0 and min(m1 - 1, m2) >= 1:
                ans = max(ans, min(m1 - 1, m2))

            # Case 3: Three blocks provide 1 + 1 + 1 = 3 occurrences
            if m3 >= 1:
                ans = max(ans, m3)

        return ans

class Solution:
    def selfDivisiblePermutationCount(self, n: int) -> int:
        from math import gcd

        # Precompute valid numbers for each position
        valid = {}
        for pos in range(1, n + 1):
            valid[pos] = []
            for num in range(1, n + 1):
                if gcd(num, pos) == 1:
                    valid[pos].append(num)

        memo = {}

        def dfs(mask, pos):
            if pos > n:
                return 1
            if mask in memo:
                return memo[mask]

            count = 0
            for num in valid[pos]:
                if not (mask & (1 << num)):  # if num is not yet used
                    count += dfs(mask | (1 << num), pos + 1)

            memo[mask] = count
            return count

        return dfs(0, 1)

