from collections import deque

class Solution:
    def minimumOperationsToMakeEqual(self, x: int, y: int) -> int:
        if x <= y:
            return y - x

        max_val = x + 11
        dist = [-1] * (max_val + 1)
        dist[x] = 0
        queue = deque([x])

        while queue:
            curr = queue.popleft()

            if curr == y:
                return dist[curr]

            # Operation 1: Divide by 11
            if curr % 11 == 0:
                nxt = curr // 11
                if dist[nxt] == -1:
                    dist[nxt] = dist[curr] + 1
                    queue.append(nxt)

            # Operation 2: Divide by 5
            if curr % 5 == 0:
                nxt = curr // 5
                if dist[nxt] == -1:
                    dist[nxt] = dist[curr] + 1
                    queue.append(nxt)

            # Operation 3: Decrement by 1
            nxt = curr - 1
            if nxt >= 0 and dist[nxt] == -1:
                dist[nxt] = dist[curr] + 1
                queue.append(nxt)

            # Operation 4: Increment by 1
            nxt = curr + 1
            if nxt <= max_val and dist[nxt] == -1:
                dist[nxt] = dist[curr] + 1
                queue.append(nxt)

        return -1

class Solution:
    def numberOfPowerfulInt(self, start: int, finish: int, limit: int, s: str) -> int:
        def count_up_to(n, limit):
            if n < 0:
                return 0
            if n == 0:
                return 1

            s_str = str(n)
            m = len(s_str)
            result = 1  # count 0

            # Count numbers with j digits, 1 <= j < m
            for j in range(1, m):
                result += limit * ((limit + 1) ** (j - 1))

            # Count numbers with m digits, <= n, all digits <= limit
            for i in range(m):
                d = int(s_str[i])
                if i == 0:
                    low = 1
                    high = min(d - 1, limit)
                else:
                    low = 0
                    high = min(d - 1, limit)

                if high >= low:
                    result += (high - low + 1) * ((limit + 1) ** (m - i - 1))

                if d > limit:
                    break
            else:
                # All digits of n are <= limit, so n itself is valid
                result += 1

            return result

        len_s = len(s)
        s_val = int(s)
        power = 10 ** len_s

        # k * power + s_val >= start  =>  k >= ceil((start - s_val) / power)
        # Using integer arithmetic: ceil(a/b) = -(-a // b) for b > 0
        k_min = max(0, -(-(start - s_val) // power))
        # k * power + s_val <= finish  =>  k <= floor((finish - s_val) / power)
        k_max = (finish - s_val) // power

        if k_max < k_min:
            return 0

        return count_up_to(k_max, limit) - count_up_to(k_min - 1, limit)

class Solution:
    def minMovesToCaptureTheQueen(self, a: int, b: int, c: int, d: int, e: int, f: int) -> int:
        # Check if the Rook can capture the Queen in 1 move
        rook_can_capture = False
        if a == e:
            # Rook and Queen are on the same row
            # Check if the Bishop is blocking the path
            if not (c == a and min(b, f) < d < max(b, f)):
                rook_can_capture = True
        elif b == f:
            # Rook and Queen are on the same column
            # Check if the Bishop is blocking the path
            if not (d == b and min(a, e) < c < max(a, e)):
                rook_can_capture = True

        # Check if the Bishop can capture the Queen in 1 move
        bishop_can_capture = False
        if abs(c - e) == abs(d - f):
            # Bishop and Queen are on the same diagonal
            # Check if the Rook is on the same diagonal and strictly between them
            bishop_blocked = (
                (abs(a - c) == abs(b - d)) and 
                (min(c, e) < a < max(c, e)) and 
                (min(d, f) < b < max(d, f))
            )
            if not bishop_blocked:
                bishop_can_capture = True

        # If either piece can capture the Queen in 1 move, return 1.
        # Otherwise, it will always take exactly 2 moves 
        # (either by moving the blocking piece out of the way, 
        # or by repositioning the attacking piece).
        if rook_can_capture or bishop_can_capture:
            return 1
        return 2

class Solution:
    def maxPartitionsAfterOperations(self, s: str, k: int) -> int:
        N = len(s)
        char_at = [ord(ch) - 97 for ch in s]

        # next_occ[i][c] stores the first occurrence of character c at or after index i
        next_occ = [[N] * 26 for _ in range(N + 1)]
        for i in range(N - 1, -1, -1):
            no_i = next_occ[i]
            no_next = next_occ[i+1]
            for c in range(26):
                no_i[c] = no_next[c]
            no_i[char_at[i]] = i

        # sorted_chars[i] stores characters sorted by their next occurrence from index i
        sorted_chars = []
        for i in range(N + 1):
            sorted_chars.append(sorted(range(26), key=lambda c: next_occ[i][c]))

        # next_pos[i] is the end of the longest prefix starting at i with <= k distinct characters
        next_pos = [0] * (N + 1)
        counts = [0] * 26
        distinct = 0
        j = 0
        for i in range(N):
            if j < i:
                j = i
                counts = [0] * 26
                distinct = 0
            while j < N:
                c = char_at[j]
                if counts[c] == 0:
                    if distinct == k:
                        break
                    distinct += 1
                counts[c] += 1
                j += 1
            next_pos[i] = j
            c = char_at[i]
            counts[c] -= 1
            if counts[c] == 0:
                distinct -= 1

        # dp[i] is the max partitions for the suffix s[i:]
        dp = [0] * (N + 1)
        partition_start = [0] * N
        partitions_before = [0] * (N + 1)

        for i in range(N - 1, -1, -1):
            dp[i] = 1 + dp[next_pos[i]]

        p = 0
        count = 0
        while p < N:
            partitions_before[p] = count
            nxt = next_pos[p]
            for i in range(p, nxt):
                partition_start[i] = p
            p = nxt
            count += 1

        def find_y(start_idx, current_mask):
            idx = start_idx
            mask = current_mask
            while idx < N:
                for c in sorted_chars[idx]:
                    if not (mask & (1 << c)):
                        min_next = next_occ[idx][c]
                        break
                else:
                    return N

                mask |= (1 << char_at[min_next])
                if mask.bit_count() > k:
                    return min_next
                idx = min_next + 1
            return N

        max_parts = dp[0]
        current_partition_start = 0
        mask_before = 0

        for i in range(N):
            if i == next_pos[current_partition_start]:
                current_partition_start = i
                mask_before = 0

            x0 = current_partition_start
            k_before = mask_before.bit_count()

            if k_before < k:
                y0_same = find_y(i + 1, mask_before)
                for c in range(26):
                    if c == char_at[i]:
                        continue
                    if mask_before & (1 << c):
                        total = partitions_before[x0] + 1 + dp[y0_same]
                    else:
                        y0 = find_y(i + 1, mask_before | (1 << c))
                        total = partitions_before[x0] + 1 + dp[y0]
                    if total > max_parts:
                        max_parts = total
            else:
                y0_same = find_y(i + 1, mask_before)
                for c in range(26):
                    if c == char_at[i]:
                        continue
                    if mask_before & (1 << c):
                        total = partitions_before[x0] + 1 + dp[y0_same]
                    else:
                        y1 = find_y(i, 1 << c)
                        total = partitions_before[x0] + 2 + dp[y1]
                    if total > max_parts:
                        max_parts = total

            mask_before |= (1 << char_at[i])

        return max_parts

