class Solution:
    def findMaximumNumber(self, k: int, x: int) -> int:
        def accumulated_price(num):
            total = 0
            p = x
            while (1 << (p - 1)) <= num:
                cycle = 1 << p
                half = cycle >> 1
                n = num + 1
                total += (n // cycle) * half + max(0, n % cycle - half)
                p += x
            return total

        lo, hi = 1, 10**15
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if accumulated_price(mid) <= k:
                lo = mid
            else:
                hi = mid - 1
        return lo

