class Solution:
    def countOfPairs(self, n: int, x: int, y: int) -> List[int]:
        result = [0] * n
        for i in range(1, n + 1):
            for j in range(1, n + 1):
                if i == j:
                    continue
                dist = min(
                    abs(i - j),
                    abs(i - x) + 1 + abs(y - j),
