class Solution:
    def countOfPairs(self, n: int, x: int, y: int) -> List[int]:
        if x > y:
            x, y = y, x

        L1 = x - 1
        R = y - x + 1
        L2 = n - y

        def P(n_val):
            if n_val < 0:
                return 0
            return min(1 + 2 * n_val, R)

        result = []
        for k in range(1, n + 1):
            # C1: pairs within Tail 1
            c1 = max(0, L1 - k)

            # C2: pairs within Tail 2
            c2 = max(0, L2 - k)

            # C3: pairs within Ring (cycle of R nodes)
            if 2 * k < R:
                c3 = R
            elif 2 * k == R:
                c3 = R // 2
            else:
                c3 = 0

            # C4: pairs between Tail 1 and Ring
            if L1 == 0:
                c4 = 0
            else:
                a = max(0, k - L1)
                b = min(k - 1, R // 2)
                if a > b:
                    c4 = 0
                else:
                    c4 = P(b) - P(a - 1)

            # C5: pairs between Tail 2 and Ring
            if L2 == 0:
                c5 = 0
            else:
                a = max(0, k - L2)
                b = min(k - 1, R // 2)
                if a > b:
                    c5 = 0
                else:
                    c5 = P(b) - P(a - 1)

            # C6: pairs between Tail 1 and Tail 2
            if L1 == 0 or L2 == 0:
                c6 = 0
            else:
                if x < y:
                    s = k - 1
                    lo = max(1, s - L2)
                    hi = min(L1, s - 1)
                else:
                    lo = max(1, k - L2)
                    hi = min(L1, k - 1)
                c6 = max(0, hi - lo + 1)

            total = c1 + c2 + c3 + c4 + c5 + c6
            result.append(2 * total)

        return result

class Solution:
    def maximumProcessableQueries(self, nums: List[int], queries: List[int]) -> int:
        n = len(nums)
        m = len(queries)

        dp = [[0] * n for _ in range(n)]

        for k in range(m - 1, -1, -1):
            new_dp = [[0] * n for _ in range(n)]
            q = queries[k]
            for length in range(n):
                max_val = length + 1
                for i in range(n - length):
                    j = i + length
                    if length > 0:
                        v1 = new_dp[i + 1][j]
                        v2 = new_dp[i][j - 1]
                        res = v1 if v1 > v2 else v2
                    else:
                        res = 0

                    if res < max_val:
                        if nums[i] >= q:
                            v = (1 + dp[i + 1][j]) if length > 0 else 1
                            if v > res:
                                res = v
                        if res < max_val and nums[j] >= q:
                            v = (1 + dp[i][j - 1]) if length > 0 else 1
                            if v > res:
                                res = v

                    new_dp[i][j] = res
            dp = new_dp

        return dp[0][n - 1]

class Solution:
    def minOrAfterOperations(self, nums: List[int], k: int) -> int:
        n = len(nums)
        target_parts = n - k
        mask = 0

        for b in range(29, -1, -1):
            mask |= (1 << b)
            count = 0
            current_and = (1 << 30) - 1
            for num in nums:
                current_and &= num
                if current_and & mask == 0:
                    count += 1
                    current_and = (1 << 30) - 1

            if count < target_parts:
                mask &= ~(1 << b)

        return ((1 << 30) - 1) & ~mask

class Solution:
    def numberOfPairs(self, points: List[List[int]]) -> int:
        n = len(points)
        count = 0

        for i in range(n):
            for j in range(n):
                if i == j:
                    continue

                ax, ay = points[i]
                bx, by = points[j]

                # Check if A is on the upper left side of B
                # A.x <= B.x and A.y >= B.y
                if ax <= bx and ay >= by:
                    # Check if any other point is inside or on the border
                    # of the rectangle formed by A and B
                    valid = True
                    for k in range(n):
                        if k == i or k == j:
                            continue
                        cx, cy = points[k]
                        if ax <= cx <= bx and by <= cy <= ay:
                            valid = False
                            break

                    if valid:
                        count += 1

        return count

class Solution:
    def maximumSubarraySum(self, nums: List[int], k: int) -> int:
        min_prefix = {}
        max_sum = float('-inf')
        prefix = 0

        for j in range(len(nums)):
            # Check if we can form a good subarray ending at j
            target1 = nums[j] - k
            target2 = nums[j] + k

            if target1 in min_prefix:
                max_sum = max(max_sum, prefix + nums[j] - min_prefix[target1])
            if target2 in min_prefix:
                max_sum = max(max_sum, prefix + nums[j] - min_prefix[target2])

            # Update running prefix sum to include nums[j]
            prefix += nums[j]

            # Store the prefix sum BEFORE nums[j] for future lookups
            prev_prefix = prefix - nums[j]
            if nums[j] not in min_prefix or prev_prefix < min_prefix[nums[j]]:
                min_prefix[nums[j]] = prev_prefix

        return max_sum if max_sum != float('-inf') else 0

class Solution:
    def numberOfPairs(self, points: List[List[int]]) -> int:
