class Solution:
    def minimumTimeToInitialState(self, word: str, k: int) -> int:
        n = len(word)
        pi = [0] * n

        # Compute the KMP prefix function
        for i in range(1, n):
            j = pi[i - 1]
            while j > 0 and word[i] != word[j]:
                j = pi[j - 1]
            if word[i] == word[j]:
                j += 1
            pi[i] = j

        # Check all valid prefix-suffix lengths
        x = pi[n - 1]
        while x > 0:
            idx = n - x
            if idx % k == 0:
                return idx // k
            x = pi[x - 1]

        # If no valid prefix-suffix match is found, we must wait until the whole string is replaced
        return (n + k - 1) // k

