        from collections import Counter

        char_count = Counter()
        for word in words:
            char_count.update(word)

        total_pairs = sum(count // 2 for count in char_count.values())
        total_singles = sum(count % 2 for count in char_count.values())

        lengths = sorted(len(word) for word in words)

        count = 0
        for L in lengths:
            pairs_needed = L // 2
            if L % 2 == 0:
                if total_pairs >= pairs_needed:
                    total_pairs -= pairs_needed
                    count += 1
                else:
                    break
            else:
                if total_pairs >= pairs_needed:
                    if total_singles > 0:
                        total_singles -= 1
                        total_pairs -= pairs_needed
                        count += 1
                    elif total_pairs > pairs_needed:
                        # Break a pair to get a center character
                        total_pairs -= pairs_needed + 1
                        total_singles += 1
                        count += 1
                    else:
                        break
                else:
                    break

        return count

