class Solution:
    def earliestSecondToMarkIndices(self, nums: List[int], changeIndices: List[int]) -> int:
        n = len(nums)
        m = len(changeIndices)

        def check(L: int) -> bool:
            last_occurrence = {}
            for i in range(L):
                last_occurrence[changeIndices[i]] = i + 1  # 1-indexed time

            # If not all indices are present in the prefix, it's impossible
            if len(last_occurrence) < n:
                return False

            times = []
            for idx, t in last_occurrence.items():
                times.append((t, idx))

            # Sort by the time we mark the index
            times.sort()

            current_sum = 0
            for k, (t, idx) in enumerate(times):
                current_sum += nums[idx - 1]
                # We need at least `current_sum` free seconds before time `t`
                # The number of free seconds before `t` is `t - (k + 1)`
                if t - (k + 1) < current_sum:
                    return False
            return True

        # If it's not possible even with all m seconds, return -1
        if not check(m):
            return -1

        # Binary search for the earliest valid second
        left, right = 1, m
        ans = m
        while left <= right:
            mid = (left + right) // 2
            if check(mid):
                ans = mid
                right = mid - 1
            else:
                left = mid + 1

        return ans

