class Solution:
    def gameResult(self, head: Optional[ListNode]) -> str:
        odd_points = 0
        even_points = 0
        curr = head

        while curr and curr.next:
            even_val = curr.val
            odd_val = curr.next.val

            if odd_val > even_val:
                odd_points += 1
            else:
                even_points += 1

            curr = curr.next.next

        if odd_points > even_points:
            return "Odd"
        elif even_points > odd_points:
            return "Even"
        else:
            return "Tie"

