class Solution:
    def countPairsOfConnectableServers(self, edges: List[List[int]], signalSpeed: int) -> List[int]:
        n = len(edges) + 1
        adj = [[] for _ in range(n)]
        for u, v, w in edges:
            adj[u].append((v, w))
            adj[v].append((u, w))

        result = [0] * n

        for c in range(n):
            running_sum = 0
            pairs = 0

            for neighbor, weight in adj[c]:
                # DFS to count vertices in this subtree with distance divisible by signalSpeed
                count = 0
                stack = [(neighbor, c, weight)]  # (node, parent, dist_from_c)
                while stack:
                    node, parent, dist = stack.pop()
                    if dist % signalSpeed == 0:
                        count += 1
                    for next_node, next_weight in adj[node]:
                        if next_node != parent:
                            stack.append((next_node, node, dist + next_weight))

                # Pairs formed by combining this subtree's valid vertices 
                # with all previously seen subtrees' valid vertices
                pairs += count * running_sum
                running_sum += count

            result[c] = pairs

        return result

