class Solution:
    def minimumOperationsToWriteY(self, grid: List[List[int]]) -> int:
        n = len(grid)
        mid = n // 2

        # Collect all Y cells using a set to avoid duplicates
        y_cells = set()

        # Top-left diagonal to center
        for i in range(mid + 1):
            y_cells.add((i, i))

        # Top-right diagonal to center
        for i in range(mid + 1):
            y_cells.add((i, n - 1 - i))

        # Vertical line from center to bottom
        for i in range(mid, n):
            y_cells.add((i, mid))

        # Count frequencies of values in Y and non-Y cells
        y_count = [0, 0, 0]
        non_y_count = [0, 0, 0]

        for r in range(n):
            for c in range(n):
                val = grid[r][c]
                if (r, c) in y_cells:
                    y_count[val] += 1
                else:
                    non_y_count[val] += 1

        total_y = len(y_cells)
        total_non_y = n * n - total_y

        # Try all valid pairs (y_val, non_y_val) where y_val != non_y_val
        min_ops = float('inf')
        for y_val in range(3):
            for non_y_val in range(3):
                if y_val != non_y_val:
                    # Operations needed = cells in Y not equal to y_val + cells not in Y not equal to non_y_val
                    ops = (total_y - y_count[y_val]) + (total_non_y - non_y_count[non_y_val])
                    min_ops = min(min_ops, ops)

        return min_ops

class Solution:
    def maximumTripletValue(self, nums: List[int]) -> int:
        n = len(nums)

        # Compute suffix max: suffix_max[j] = max(nums[j+1..n-1])
        suffix_max = [0] * n
        for i in range(n - 2, -1, -1):
            suffix_max[i] = max(suffix_max[i + 1], nums[i + 1])

        # Coordinate compression for the BIT
        sorted_unique = sorted(set(nums))
        rank = {v: i + 1 for i, v in enumerate(sorted_unique)}
        max_rank = len(sorted_unique)

        # Left BIT: supports prefix max queries
        left_bit = [0] * (max_rank + 1)

        def left_update(pos, val):
            while pos <= max_rank:
                if val > left_bit[pos]:
                    left_bit[pos] = val
                pos += pos & (-pos)

        def left_query(pos):
            res = 0
            while pos > 0:
                if left_bit[pos] > res:
                    res = left_bit[pos]
                pos -= pos & (-pos)
            return res

        ans = 0
        for j in range(n):
            r = rank[nums[j]]

            # Query max_left: max value with rank strictly less than r
            max_left = 0
            if r > 1:
                max_left = left_query(r - 1)

            # max_right is suffix_max[j] if it's strictly greater than nums[j]
            max_right = suffix_max[j]

            if max_left > 0 and max_right > nums[j]:
                val = max_left - nums[j] + max_right
                if val > ans:
                    ans = val

            # Insert nums[j] into the BIT
            left_update(r, nums[j])

        return ans

