        from collections import defaultdict

        # Count how many distinct strings contain each substring
        sub_count = defaultdict(int)
        for s in arr:
            seen = set()
            for length in range(1, len(s) + 1):
                for start in range(len(s) - length + 1):
                    seen.add(s[start:start + length])
            for sub in seen:
                sub_count[sub] += 1

        answer = []
        for s in arr:
            best = None
            # Check substrings by increasing length
            for length in range(1, len(s) + 1):
                candidates = []
                for start in range(len(s) - length + 1):
                    sub = s[start:start + length]
                    if sub_count[sub] == 1:
                        candidates.append(sub)
                if candidates:
                    candidates.sort()
                    best = candidates[0]
                    break
            if best is None:
                answer.append("")
            else:
