class Solution:
    def findPattern(self, board: List[List[int]], pattern: List[str]) -> List[int]:
        R = len(pattern)
        C = len(pattern[0])
        rows = len(board)
        cols = len(board[0])

        # Collect fixed digits from pattern
        fixed_digits = set()
        for i in range(R):
            for j in range(C):
                if pattern[i][j].isdigit():
                    fixed_digits.add(int(pattern[i][j]))

        for r in range(rows - R + 1):
            for c in range(cols - C + 1):
                letter_to_digit = {}
                used_digits = set(fixed_digits)
                match = True

                for i in range(R):
                    if not match:
                        break
                    for j in range(C):
                        p = pattern[i][j]
                        val = board[r + i][c + j]

                        if p.isdigit():
                            if val != int(p):
                                match = False
                                break
                        else:
                            if p in letter_to_digit:
                                if val != letter_to_digit[p]:
                                    match = False
                                    break
                            else:
                                if val in used_digits:
                                    match = False
                                    break
                                letter_to_digit[p] = val
                                used_digits.add(val)

                if match:
                    return [r, c]

        return [-1, -1]

import heapq

class Solution:
    def minimizeStringValue(self, s: str) -> str:
        # Count frequencies of fixed characters
        count = [0] * 26
        for c in s:
            if c != '?':
                count[ord(c) - ord('a')] += 1

        # Min-heap of (current_count, character_index)
        heap = [(count[i], i) for i in range(26)]
        heapq.heapify(heap)

        q_count = s.count('?')
        chosen_counts = [0] * 26

        # Greedily pick the character with minimum current frequency
        # Ties broken by smallest character index (lexicographically smallest)
        for _ in range(q_count):
            cnt, idx = heapq.heappop(heap)
            chosen_counts[idx] += 1
            heapq.heappush(heap, (cnt + 1, idx))

        # Build result: place chosen characters in sorted order at '?' positions
        result = []
        q_idx = 0
        for c in s:
            if c == '?':
                # Find next available character in alphabetical order
                while chosen_counts[q_idx] == 0:
                    q_idx += 1
                result.append(chr(q_idx + ord('a')))
                chosen_counts[q_idx] -= 1
            else:
                result.append(c)

        return ''.join(result)

