        return k * (k + 1) // 2

class Solution:
    def makeAntiPalindrome(self, s: str) -> str:
        n = len(s)
        from collections import Counter
        freq = Counter(s)
        if max(freq.values()) > n // 2:
            return "-1"

        c = sorted(s)

        # Find the first bad pair index
        L_bad = -1
        for i in range(n // 2):
            if c[i] == c[n - 1 - i]:
                L_bad = i
                break

        # If no bad pairs, sorted string is already the answer
        if L_bad == -1:
            return "".join(c)

        # Find the full range [L_prime, R] of the character causing bad pairs
        x = c[L_bad]
        L_prime = L_bad
        while L_prime > 0 and c[L_prime - 1] == x:
            L_prime -= 1

        R = L_bad
        while R < n - 1 and c[R + 1] == x:
            R += 1

        # Number of bad pairs to fix
        num_bad = n // 2 - L_bad

        # Valid swap targets: positions k where mirror n-1-k doesn't have 'x'
        # This requires k >= n - L_prime (mirror < L_prime, so mirror char < x)
        start = max(R + 1, n - L_prime)

        # Swap bad pair positions in second half with valid targets
        for i in range(num_bad):
            c[n // 2 + i], c[start + i] = c[start + i], c[n // 2 + i]

        return "".join(c)

class Solution:
    def maximumLengthSubstring(self, s: str) -> int:
        left = 0
        max_len = 0
        counts = {}

        for right in range(len(s)):
            char = s[right]
            counts[char] = counts.get(char, 0) + 1

            # If the current character appears more than twice, shrink the window from the left
            while counts[char] > 2:
                counts[s[left]] -= 1
                left += 1

            # Update the maximum length found so far
            max_len = max(max_len, right - left + 1)

        return max_len

class Solution:
    def minOperations(self, k: int) -> int:
        if k == 1:
            return 0

        min_ops = float('inf')
        for v in range(1, k + 1):
            # Number of duplications needed: ceil(k / v) - 1
            # Using integer arithmetic: ceil(k / v) = (k + v - 1) // v
            d = (k + v - 1) // v - 1
            ops = (v - 1) + d
            if ops < min_ops:
                min_ops = ops

        return min_ops

