            counts[id_val] = counts.get(id_val, 0) + f

            # Push new count to heap if positive
            if counts[id_val] > 0:
                heapq.heappush(heap, (-counts[id_val], id_val))

            # Lazy deletion: remove stale entries from the top
            while heap and counts.get(heap[0][1], 0) != -heap[0][0]:
                heapq.heappop(heap)

            # The top of the heap is the max frequency (or 0 if empty)
            if heap:
                ans.append(-heap[0][0])
            else:
                ans.append(0)

        return ans

class Solution:
    def minimumSubarrayLength(self, nums: List[int], k: int) -> int:
        n = len(nums)
        bit_count = [0] * 30
        left = 0
        min_len = float('inf')
        current_or = 0

        for right in range(n):
            # Add nums[right] to the window
            for i in range(30):
                if nums[right] & (1 << i):
                    bit_count[i] += 1
                    current_or |= (1 << i)

            # Shrink window from the left while OR >= k
            while current_or >= k and left <= right:
                min_len = min(min_len, right - left + 1)
                # Remove nums[left] from the window
                for i in range(30):
                    if nums[left] & (1 << i):
                        bit_count[i] -= 1
                        if bit_count[i] == 0:
                            current_or &= ~(1 << i)
                left += 1

        return min_len if min_len != float('inf') else -1

class Solution:
