class Solution:
    def maxSubstringLength(self, s: str) -> int:
        n = len(s)

        first = {}
        last = {}
        for i, c in enumerate(s):
            if c not in first:
                first[c] = i
            last[c] = i

        F = list(set(first.values()))
        L = list(set(last.values()))

        A = [first[c] for c in s]
        B = [last[c] for c in s]

        LOG = n.bit_length()

        # Sparse table for range minimum of A
        st_min = [A[:]]
        for j in range(1, LOG):
            prev = st_min[j - 1]
            half = 1 << (j - 1)
            length = n - (1 << j) + 1
            st_min.append([min(prev[i], prev[i + half]) for i in range(length)])

        # Sparse table for range maximum of B
        st_max = [B[:]]
        for j in range(1, LOG):
            prev = st_max[j - 1]
            half = 1 << (j - 1)
            length = n - (1 << j) + 1
            st_max.append([max(prev[i], prev[i + half]) for i in range(length)])

        def query_min(l, r):
            k = (r - l + 1).bit_length() - 1
            return min(st_min[k][l], st_min[k][r - (1 << k) + 1])

        def query_max(l, r):
            k = (r - l + 1).bit_length() - 1
            return max(st_max[k][l], st_max[k][r - (1 << k) + 1])

        # Collect valid candidate pairs and sort by length descending
        pairs = []
        for i in F:
            for j in L:
                if i <= j and (i, j) != (0, n - 1):
                    pairs.append((j - i + 1, i, j))

        pairs.sort(reverse=True)

        ans = -1
        for length, i, j in pairs:
            if length <= ans:
                break
            if query_min(i, j) >= i and query_max(i, j) <= j:
                ans = length

        return ans

class Solution:
    def getSmallestString(self, s: str, k: int) -> str:
        result = []
        for ch in s:
            for c in 'abcdefghijklmnopqrstuvwxyz':
                dist = min(abs(ord(ch) - ord(c)), 26 - abs(ord(ch) - ord(c)))
                if dist <= k:
                    result.append(c)
                    k -= dist
                    break
        return ''.join(result)

class Solution:
    def minimumCost(self, n: int, edges: List[List[int]], query: List[List[int]]) -> List[int]:
        parent = list(range(n))
        rank = [0] * n

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(x, y):
            px, py = find(x), find(y)
            if px == py:
                return
            if rank[px] < rank[py]:
                px, py = py, px
            parent[py] = px
            if rank[px] == rank[py]:
                rank[px] += 1

        # Build connected components
        for u, v, w in edges:
            union(u, v)

        # Initialize AND value for each component
        # -1 in Python has all bits set, so -1 & x == x for any non-negative x
        comp_and = {}
        for i in range(n):
            root = find(i)
            if root not in comp_and:
                comp_and[root] = -1

        # Compute AND of all edge weights in each component
        for u, v, w in edges:
            root = find(u)
            comp_and[root] &= w

        # Answer queries
        result = []
        for s, t in query:
            rs, rt = find(s), find(t)
            if rs != rt:
                result.append(-1)
            else:
                result.append(comp_and[rs])

        return result

class Solution:
