            if res[1] == '?' or res[1] in '01':
                res[0] = '1'
            else:
                res[0] = '0'

        if res[1] == '?':
            if res[0] == '1':
                res[1] = '1'
            else:
                res[1] = '9'

        # Handle the minute part
        if res[3] == '?':
            res[3] = '5'

        if res[4] == '?':
            res[4] = '9'

        return "".join(res)

class Solution:
    def maximumPrimeDifference(self, nums: List[int]) -> int:
        def is_prime(n):
            if n <= 1:
                return False
            if n <= 3:
                return True
            if n % 2 == 0 or n % 3 == 0:
                return False
            i = 5
            while i * i <= n:
                if n % i == 0 or n % (i + 2) == 0:
                    return False
                i += 6
            return True

        first = -1
        last = -1
        for i, num in enumerate(nums):
            if is_prime(num):
                if first == -1:
                    first = i
                last = i

        return last - first

