class Solution:
    def findKthSmallest(self, coins: List[int], k: int) -> int:
        n = len(coins)
        lcm_list = []
        sign_list = []

        # Precompute LCM and inclusion-exclusion sign for every non-empty subset
        for mask in range(1, 1 << n):
            current_lcm = 1
            bits = 0
            for i in range(n):
                if mask & (1 << i):
                    bits += 1
                    current_lcm = current_lcm * coins[i] // gcd(current_lcm, coins[i])
            lcm_list.append(current_lcm)
            sign_list.append(1 if bits % 2 == 1 else -1)

        # Count how many distinct amounts are <= x using inclusion-exclusion
        def count(x):
            total = 0
            for lcm, sign in zip(lcm_list, sign_list):
                total += sign * (x // lcm)
            return total

        # Binary search for the smallest x such that count(x) >= k
        lo, hi = 1, k * min(coins)
        while lo < hi:
            mid = (lo + hi) // 2
            if count(mid) >= k:
                hi = mid
            else:
                lo = mid + 1

        return lo

