class Solution:
    def minimumValueSum(self, nums: List[int], andValues: List[int]) -> int:
        n = len(nums)
        m = len(andValues)
        ALL_ONES = (1 << 17) - 1  # 17 bits sufficient since nums[i] < 10^5 < 2^17
        INF = 10**9

        # dp[j] maps mask -> minimum cost for j completed subarrays
        dp = [{} for _ in range(m + 1)]
        dp[0][ALL_ONES] = 0

        for i in range(n):
            new_dp = [{} for _ in range(m + 1)]
            num = nums[i]

            for j in range(m):
                for mask, cost in dp[j].items():
                    new_mask = mask & num

                    # Option 1: Continue the current subarray
                    if cost < new_dp[j].get(new_mask, INF):
                        new_dp[j][new_mask] = cost

                    # Option 2: End the current subarray here
                    if new_mask == andValues[j]:
                        new_cost = cost + num
                        if new_cost < new_dp[j + 1].get(ALL_ONES, INF):
                            new_dp[j + 1][ALL_ONES] = new_cost

            dp = new_dp

        return dp[m].get(ALL_ONES, -1)

class Solution:
    def maxPotholes(self, road: str, budget: int) -> int:
        # Find all groups of consecutive potholes
        groups = []
        count = 0
        for c in road:
            if c == 'x':
                count += 1
            else:
                if count > 0:
                    groups.append(count)
                    count = 0
        if count > 0:
            groups.append(count)

        # Greedy: process largest groups first for best efficiency
        groups.sort(reverse=True)

        total_fixed = 0
        for n in groups:
            if budget >= n + 1:
                # Can fix the entire group
                total_fixed += n
                budget -= n + 1
            elif budget >= 2:
                # Can partially fix this group: fix (budget - 1) potholes
                total_fixed += budget - 1
                budget = 0
            else:
                # Not enough budget for even 1 pothole (cost = 2)
                break

        return total_fixed

