            if last_lower != -1 and first_upper != -1 and last_lower < first_upper:
                count += 1

        return count

class Solution:
    def minimumOperations(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])

        # Count frequency of each digit (0-9) in each column
        count = [[0] * 10 for _ in range(n)]
        for i in range(m):
            for j in range(n):
                count[j][grid[i][j]] += 1

        # dp[v] = min operations so that current column has value v
        dp = [m - count[0][v] for v in range(10)]

        for j in range(1, n):
            # Find the smallest and second smallest values in dp
            min1 = float('inf')
            min2 = float('inf')
            min1_idx = -1
            for v in range(10):
                if dp[v] < min1:
                    min2 = min1
                    min1 = dp[v]
                    min1_idx = v
                elif dp[v] < min2:
                    min2 = dp[v]

            new_dp = [0] * 10
            for v in range(10):
                cost = m - count[j][v]
                # If v is the same as the best previous choice, use second best
                if v != min1_idx:
                    new_dp[v] = cost + min1
                else:
                    new_dp[v] = cost + min2

            dp = new_dp

        return min(dp)

