class Solution:
    def findAnswer(self, n: int, edges: List[List[int]]) -> List[bool]:
        adj = [[] for _ in range(n)]
        for u, v, w in edges:
            adj[u].append((v, w))
            adj[v].append((u, w))

        INF = 10**18

        def dijkstra(start):
            dist = [INF] * n
            dist[start] = 0
            pq = [(0, start)]
            while pq:
                d, u = heapq.heappop(pq)
                if d > dist[u]:
                    continue
                for v, w in adj[u]:
                    if dist[u] + w < dist[v]:
                        dist[v] = dist[u] + w
                        heapq.heappush(pq, (dist[v], v))
            return dist

        dist0 = dijkstra(0)
        distN = dijkstra(n - 1)

        D = dist0[n - 1]
        if D == INF:
            return [False] * len(edges)

        return [
            dist0[u] + w + distN[v] == D or dist0[v] + w + distN[u] == D
            for u, v, w in edges
        ]

