class Solution:
    def numberOfStableArrays(self, zero: int, one: int, limit: int) -> int:
        MOD = 10**9 + 7

        dp0 = [[0] * (one + 1) for _ in range(zero + 1)]
        dp1 = [[0] * (one + 1) for _ in range(zero + 1)]

        # Base cases: arrays of all 0s or all 1s
        for i in range(1, min(zero, limit) + 1):
            dp0[i][0] = 1
        for j in range(1, min(one, limit) + 1):
            dp1[0][j] = 1

        # Sliding window sum for dp1 values along columns
        col_sum1 = [0] * (one + 1)

        for i in range(zero + 1):
            # Update col_sum1: add dp1[i-1][j], remove dp1[i-1-limit][j]
            if i >= 1:
                for j in range(one + 1):
                    col_sum1[j] = (col_sum1[j] + dp1[i - 1][j]) % MOD
            if i - 1 - limit >= 0:
                for j in range(one + 1):
                    col_sum1[j] = (col_sum1[j] - dp1[i - 1 - limit][j]) % MOD

            # Sliding window sum for dp0 values along current row
            row_sum = 0
            for j in range(one + 1):
                # Compute dp0[i][j] using column sliding window
                if j > 0:
                    dp0[i][j] = col_sum1[j]

                # Update row sliding window: add dp0[i][j-1], remove dp0[i][j-1-limit]
                if j >= 1:
                    row_sum = (row_sum + dp0[i][j - 1]) % MOD
                if j - 1 - limit >= 0:
                    row_sum = (row_sum - dp0[i][j - 1 - limit]) % MOD

                # Compute dp1[i][j] using row sliding window
                if i > 0:
                    dp1[i][j] = row_sum

        return (dp0[zero][one] + dp1[zero][one]) % MOD

