class Solution:
    def minimumAddedInteger(self, nums1: List[int], nums2: List[int]) -> int:
        nums1.sort()
        nums2.sort()

        # The first element of the remaining nums1 can be at index 0, 1, or 2
        candidates = sorted([nums2[0] - nums1[i] for i in range(3)])

        for x in candidates:
            j = 0  # pointer for nums2
            skips = 0
            for i in range(len(nums1)):
                if j < len(nums2) and nums1[i] + x == nums2[j]:
                    j += 1
                else:
                    skips += 1
                if skips > 2:
                    break
            if j == len(nums2):
                return x

        return -1

class Solution:
    def minEnd(self, n: int, x: int) -> int:
        result = x
        n -= 1  # We need to find the (n-1)-th number after x

        # Embed the bits of (n-1) into the 0-bit positions of x
        bit_pos = 0
        while n > 0:
            if (result & (1 << bit_pos)) == 0:
                # This is a 0-bit position in x, use it for the current bit of n
                if n & 1:
                    result |= (1 << bit_pos)
                n >>= 1
            bit_pos += 1

        return result

class Solution:
    def minOperations(self, initial: str, target: str) -> int:
        n = len(initial)
        m = len(target)

        # Find the length of the longest common substring
        max_len = 0
        prev = [0] * (m + 1)

        for i in range(1, n + 1):
            curr = [0] * (m + 1)
            for j in range(1, m + 1):
                if initial[i - 1] == target[j - 1]:
                    curr[j] = prev[j - 1] + 1
                    if curr[j] > max_len:
                        max_len = curr[j]
            prev = curr

        # Minimum operations = characters to remove + characters to add
        return n + m - 2 * max_len

class Solution:
    def minAnagramLength(self, s: str) -> int:
        n = len(s)

        # Compute total character frequencies
        freq_s = [0] * 26
        for c in s:
            freq_s[ord(c) - 97] += 1

        # Find all divisors of n, sorted ascending
        divisors = []
        for i in range(1, int(n**0.5) + 1):
            if n % i == 0:
                divisors.append(i)
                if i != n // i:
                    divisors.append(n // i)
        divisors.sort()

        for L in divisors:
            k = n // L

            # Quick check: every character count must be divisible by k
            if any(count % k != 0 for count in freq_s):
                continue

            # Compute target frequency from the first block
            target = [0] * 26
            for i in range(L):
                target[ord(s[i]) - 97] += 1

            # Verify all remaining blocks match the target frequency
            all_same = True
            for block in range(1, k):
                start = block * L
                bf = [0] * 26
                for i in range(start, start + L):
                    bf[ord(s[i]) - 97] += 1
                if bf != target:
                    all_same = False
                    break

            if all_same:
                return L

        return n

class Solution:
    def minCostToEqualizeArray(self, nums: List[int], cost1: int, cost2: int) -> int:
        MOD = 10**9 + 7
        n = len(nums)
        max_val = max(nums)
        min_val = min(nums)
        total_sum = sum(nums)

        if max_val == min_val:
            return 0

        if n == 1:
            return 0

        if n == 2:
            return ((max_val - min_val) * cost1) % MOD

        if cost2 >= 2 * cost1:
            S = n * max_val - total_sum
            return (S * cost1) % MOD

        # cost2 < 2 * cost1 and n >= 3
        candidates = set()
        candidates.add(max_val)
        candidates.add(max_val + 1)
        candidates.add(max_val + 2)

        # T_boundary is where 2 * max_d == S
        # 2 * (T - min_val) = n * T - total_sum
        # T * (n - 2) = total_sum - 2 * min_val
        T_boundary = (total_sum - 2 * min_val) / (n - 2)
        T_floor = int(T_boundary)

        for t in range(T_floor - 2, T_floor + 4):
            if t >= max_val:
                candidates.add(t)

        min_cost = float('inf')
        for T in candidates:
            S = n * T - total_sum
            max_d = T - min_val

            if 2 * max_d <= S:
                # Can pair all (or all but one) increments
                if S % 2 == 0:
                    cost = (S // 2) * cost2
                else:
                    cost = (S // 2) * cost2 + cost1
            else:
                # Max element dominates, can only pair S - max_d increments
                cost = (S - max_d) * cost2 + (2 * max_d - S) * cost1

            if cost < min_cost:
                min_cost = cost

        return min_cost % MOD

