class Solution:
    def minimumSubstringsInPartition(self, s: str) -> int:
        n = len(s)
        dp = [float('inf')] * (n + 1)
        dp[0] = 0

        for j in range(n):
            if dp[j] == float('inf'):
                continue
            count = [0] * 26
            distinct = 0
            max_freq = 0
            for i in range(j, n):
                c = ord(s[i]) - ord('a')
                count[c] += 1
                if count[c] == 1:
                    distinct += 1
                if count[c] > max_freq:
                    max_freq = count[c]

                length = i - j + 1
                # A substring is balanced iff all present characters 
                # have the same frequency. This is equivalent to:
                # max_freq * distinct == length
                if max_freq * distinct == length:
                    if dp[j] + 1 < dp[i + 1]:
                        dp[i + 1] = dp[j] + 1

        return dp[n]

