        n = len(energy)
        # Process from right to left, accumulating chain sums in-place
        for i in range(n - 1, -1, -1):
            if i + k < n:
                energy[i] += energy[i + k]
        return max(energy)

class Solution:
    def maxScore(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])

        # suffix_max[r][c] = max value in grid[r..m-1][c..n-1]
        suffix_max = [[0] * n for _ in range(m)]

        for r in range(m - 1, -1, -1):
            for c in range(n - 1, -1, -1):
                val = grid[r][c]
                if r + 1 < m:
                    val = max(val, suffix_max[r + 1][c])
                if c + 1 < n:
                    val = max(val, suffix_max[r][c + 1])
                suffix_max[r][c] = val

        ans = float('-inf')

        for r in range(m):
            for c in range(n):
                # Best value reachable from (r, c) excluding (r, c) itself
                best = float('-inf')
                if r + 1 < m:
                    best = max(best, suffix_max[r + 1][c])
                if c + 1 < n:
                    best = max(best, suffix_max[r][c + 1])
                if best != float('-inf'):
                    ans = max(ans, best - grid[r][c])

        return ans

import math

class Solution:
    def waysToReachStair(self, k: int) -> int:
        ans = 0
        j = 0
        while True:
            d = (1 << j) - k
            if d < 0:
                j += 1
                continue
            if d > j + 1:
                break
            ans += math.comb(j + 1, d)
            j += 1
        return ans

