        distinct_colors = 0
        result = []

        for x, y in queries:
            old_color = ball_color.get(x)

            # If the ball is already colored with the same color, nothing changes
            if old_color == y:
                result.append(distinct_colors)
                continue

            # If the ball had a previous color, decrement its count
            if old_color is not None:
                color_count[old_color] -= 1
                # If no balls have this color anymore, remove it and decrement distinct count
                if color_count[old_color] == 0:
                    distinct_colors -= 1
                    del color_count[old_color]

            # Assign the new color to the ball
            ball_color[x] = y

            # Update the count for the new color
            if y not in color_count:
                color_count[y] = 0
                distinct_colors += 1
            color_count[y] += 1

            # Record the current number of distinct colors
            result.append(distinct_colors)

        return result

class Solution:
    def clearStars(self, s: str) -> str:
        n = len(s)
        char_positions = [[] for _ in range(26)]
        deleted = [False] * n

        for i, c in enumerate(s):
            if c == '*':
                # Find the smallest character with a non-empty stack
                for j in range(26):
                    if char_positions[j]:
                        # Pop the rightmost occurrence (top of stack)
                        pos = char_positions[j].pop()
                        deleted[pos] = True
                        break
            else:
                char_positions[ord(c) - ord('a')].append(i)

        # Build the result string
        result = []
        for i in range(n):
            if not deleted[i] and s[i] != '*':
                result.append(s[i])

        return ''.join(result)

