class Solution:
    def maximumLength(self, nums: List[int], k: int) -> int:
        INF = float('inf')

        # best_all[j] stores top 2 (max_length, ending_value) pairs with different ending_values
        best_all = [[(-INF, -1), (-INF, -1)] for _ in range(k + 1)]
        # best_same[j][val] stores max length of subsequence with j transitions ending with value val
        best_same = [{} for _ in range(k + 1)]

        ans = 0

        for num in nums:
            for j in range(k + 1):
                # Base case: start a new subsequence with just this element
                res = 1 if j == 0 else -INF

                # Option 1: extend a subsequence ending with the same value (no new transition)
                if num in best_same[j]:
                    res = max(res, best_same[j][num] + 1)

                # Option 2: extend a subsequence ending with a different value (one new transition)
                if j > 0:
                    top1_val, top1_num = best_all[j - 1][0]
                    top2_val, top2_num = best_all[j - 1][1]

                    if top1_num != num:
                        res = max(res, top1_val + 1)
                    elif top2_num != num:
                        res = max(res, top2_val + 1)

                # Update answer
                if res > ans:
                    ans = res

                # Update best_same and best_all if this is a valid state
                if res > 0:
                    if num not in best_same[j] or res > best_same[j][num]:
                        best_same[j][num] = res

                    # Update best_all (maintain top 2 with different ending values)
                    if res > best_all[j][0][0]:
                        if num == best_all[j][0][1]:
                            best_all[j][0] = (res, num)
                        else:
                            best_all[j][1] = best_all[j][0]
                            best_all[j][0] = (res, num)
                    elif num != best_all[j][0][1] and res > best_all[j][1][0]:
                        best_all[j][1] = (res, num)

        return ans

class Solution:
    def maximumLength(self, nums: List[int], k: int) -> int:
        # best[j][v] = max subsequence length ending with value v, with at most j transitions
        best = [{} for _ in range(k + 1)]
        # top1[j] and top2[j] track the two largest values in best[j] with different keys
        top1 = [(0, -1) for _ in range(k + 1)]
        top2 = [(0, -1) for _ in range(k + 1)]

        ans = 0

        for num in nums:
            dp = [0] * (k + 1)
            for j in range(k + 1):
                # Base case: subsequence of just this element
                dp[j] = 1

                # Extend with same value (no new transition)
                if num in best[j]:
                    dp[j] = max(dp[j], best[j][num] + 1)

                # Extend with different value (adds 1 transition)
                if j >= 1:
                    if top1[j - 1][1] != num:
                        dp[j] = max(dp[j], top1[j - 1][0] + 1)
                    else:
                        dp[j] = max(dp[j], top2[j - 1][0] + 1)

                if dp[j] > ans:
                    ans = dp[j]

            # Update best and top1/top2 trackers
            for j in range(k + 1):
                if num not in best[j] or dp[j] > best[j][num]:
                    best[j][num] = dp[j]
                    val = dp[j]
                    if val > top1[j][0]:
                        if top1[j][1] == num:
                            top1[j] = (val, num)
                        else:
                            top2[j] = top1[j]
                            top1[j] = (val, num)
                    elif top1[j][1] != num and val > top2[j][0]:
                        top2[j] = (val, num)

        return ans

