class Solution:
    def minimumSum(self, grid: List[List[int]]) -> int:
        n = len(grid)
        m = len(grid[0])

        row_prefix = [[0] * (m + 1) for _ in range(n)]
        col_prefix = [[0] * (n + 1) for _ in range(m)]

        for r in range(n):
            for c in range(m):
                row_prefix[r][c + 1] = row_prefix[r][c] + grid[r][c]

        for c in range(m):
            for r in range(n):
                col_prefix[c][r + 1] = col_prefix[c][r] + grid[r][c]

        def get_area(r1, r2, c1, c2):
            min_r = -1
            for r in range(r1, r2):
                if row_prefix[r][c2] - row_prefix[r][c1] > 0:
                    min_r = r
                    break
            if min_r == -1:
                return 0

            max_r = -1
            for r in range(r2 - 1, r1 - 1, -1):
                if row_prefix[r][c2] - row_prefix[r][c1] > 0:
                    max_r = r
                    break

            min_c = -1
            for c in range(c1, c2):
                if col_prefix[c][r2] - col_prefix[c][r1] > 0:
                    min_c = c
                    break

            max_c = -1
            for c in range(c2 - 1, c1 - 1, -1):
                if col_prefix[c][r2] - col_prefix[c][r1] > 0:
                    max_c = c
                    break

            return (max_r - min_r + 1) * (max_c - min_c + 1)

        def calc(a1, a2, a3):
            areas = [a1, a2, a3]
            non_zero = [a for a in areas if a > 0]
            return sum(non_zero) + (3 - len(non_zero))

        ans = float('inf')

        # Config 1: 3 horizontal strips
        for i in range(1, n - 1):
            for j in range(i + 1, n):
                ans = min(ans, calc(get_area(0, i, 0, m), get_area(i, j, 0, m), get_area(j, n, 0, m)))

        # Config 2: 3 vertical strips
        for i in range(1, m - 1):
            for j in range(i + 1, m):
                ans = min(ans, calc(get_area(0, n, 0, i), get_area(0, n, i, j), get_area(0, n, j, m)))

        # Config 3: Top one, bottom two
        for i in range(1, n):
            for j in range(1, m):
                ans = min(ans, calc(get_area(0, i, 0, m), get_area(i, n, 0, j), get_area(i, n, j, m)))

        # Config 4: Bottom one, top two
        for i in range(1, n):
            for j in range(1, m):
                ans = min(ans, calc(get_area(0, i, 0, j), get_area(0, i, j, m), get_area(i, n, 0, m)))

        # Config 5: Left one, right two
        for i in range(1, n):
            for j in range(1, m):
                ans = min(ans, calc(get_area(0, n, 0, j), get_area(0, i, j, m), get_area(i, n, j, m)))

        # Config 6: Right one, left two
        for i in range(1, n):
            for j in range(1, m):
                ans = min(ans, calc(get_area(0, i, 0, j), get_area(i, n, 0, j), get_area(0, n, j, m)))

        return ans

class Solution:
    def maxHeightOfTriangle(self, red: int, blue: int) -> int:
        def get_max_height(r, b):
            h = 1
            while True:
                k_odd = (h + 1) // 2
                k_even = h // 2
                s_odd = k_odd * k_odd
                s_even = k_even * (k_even + 1)
                if s_odd <= r and s_even <= b:
                    h += 1
                else:
                    return h - 1

        return max(get_max_height(red, blue), get_max_height(blue, red))

