        n = len(nums)
        even_count = 0
        odd_count = 0
        changes = 0

        for i in range(n):
            if nums[i] % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

            if i > 0 and nums[i] % 2 != nums[i - 1] % 2:
                changes += 1

        alternating_length = 1 + changes
