class Solution:
    def numberOfSubmatrices(self, grid: List[List[str]]) -> int:
        m, n = len(grid), len(grid[0])

        # prev_x[j] and prev_y[j] store prefix sums up to the previous row
        prev_x = [0] * n
        prev_y = [0] * n

        count = 0

        for i in range(m):
            curr_x = [0] * n
            curr_y = [0] * n
            for j in range(n):
                x_val = 1 if grid[i][j] == 'X' else 0
                y_val = 1 if grid[i][j] == 'Y' else 0

                # 2D prefix sum formula:
                # curr[i][j] = prev[i-1][j] + curr[i][j-1] - prev[i-1][j-1] + val
                curr_x[j] = x_val
                if i > 0:
                    curr_x[j] += prev_x[j]
                if j > 0:
                    curr_x[j] += curr_x[j - 1]
                if i > 0 and j > 0:
                    curr_x[j] -= prev_x[j - 1]

                curr_y[j] = y_val
                if i > 0:
                    curr_y[j] += prev_y[j]
                if j > 0:
                    curr_y[j] += curr_y[j - 1]
                if i > 0 and j > 0:
                    curr_y[j] -= prev_y[j - 1]

                if curr_x[j] == curr_y[j] and curr_x[j] >= 1:
                    count += 1

            prev_x = curr_x
            prev_y = curr_y

        return count

