from typing import List

class Solution:
    def minimumCost(self, target: str, words: List[str], costs: List[int]) -> int:
        goto = [{}]
        fail = [0]
        word_info = [{}]

        for word, cost in zip(words, costs):
            node = 0
            for ch in word:
                nxt = goto[node].get(ch)
                if nxt is None:
                    nxt = len(goto)
                    goto[node][ch] = nxt
                    goto.append({})
                    fail.append(0)
                    word_info.append({})
                node = nxt
            l = len(word)
            wi = word_info[node]
            if l not in wi or cost < wi[l]:
                wi[l] = cost

        queue = deque()
        for child in goto[0].values():
            queue.append(child)

        while queue:
            node = queue.popleft()
            for ch, child in goto[node].items():
                f = fail[node]
                while f and ch not in goto[f]:
                    f = fail[f]
                fail[child] = goto[f].get(ch, 0)

                fc = fail[child]
                if fc and word_info[fc]:
                    wi = word_info[child]
                    for l, c in word_info[fc].items():
                        if l not in wi or c < wi[l]:
                            wi[l] = c

                queue.append(child)

        wi_lists = [list(wi.items()) for wi in word_info]

        n = len(target)
        INF = 10**9
        dp = [INF] * (n + 1)
        dp[0] = 0

        node = 0
        for i in range(n):
            ch = target[i]
            while node and ch not in goto[node]:
                node = fail[node]
            node = goto[node].get(ch, 0)

            wi = wi_lists[node]
            if wi:
                i1 = i + 1
                dp_i1 = dp[i1]
                for l, c in wi:
                    prev = i1 - l
                    if prev >= 0:
                        val = dp[prev] + c
                        if val < dp_i1:
                            dp_i1 = val
                dp[i1] = dp_i1

        return dp[n] if dp[n] < INF else -1

