    def minimumCost(self, m: int, n: int, horizontalCut: List[int], verticalCut: List[int]) -> int:
        # Combine all cuts with their type
        cuts = []
        for c in horizontalCut:
            cuts.append((c, 'h'))
        for c in verticalCut:
            cuts.append((c, 'v'))

        # Sort by cost in descending order (greedy: most expensive first)
        cuts.sort(reverse=True)

        h_segments = 1  # number of horizontal segments
        v_segments = 1  # number of vertical segments
        total_cost = 0

        for cost, cut_type in cuts:
            if cut_type == 'h':
                # Horizontal cut: cost multiplied by current vertical segments
                total_cost += cost * v_segments
                h_segments += 1
            else:
                # Vertical cut: cost multiplied by current horizontal segments
                total_cost += cost * h_segments
                v_segments += 1

        return total_cost

