from typing import List

class Solution:
    def minOperations(self, nums: List[int]) -> int:
        tails = []

        for x in nums:
            # Negate the value to transform the longest non-increasing subsequence 
            # problem into a longest non-decreasing subsequence problem.
            val = -x

            # Find the index where 'val' should be inserted to maintain sorted order.
            # bisect_right allows equal elements, correctly handling non-decreasing sequences.
            idx = bisect.bisect_right(tails, val)

            # If 'val' is greater than or equal to all elements in tails, extend the subsequence
            if idx == len(tails):
                tails.append(val)
            # Otherwise, overwrite the existing element to maintain the smallest possible tail
            else:
                tails[idx] = val

        # The length of tails represents the length of the longest non-increasing subsequence
        return len(tails)

