import math

class Solution:
    def nonSpecialCount(self, l: int, r: int) -> int:
        # Find the range of primes whose squares fall in [l, r]
        # lower = ceil(sqrt(l))
        lower = math.isqrt(l)
        if lower * lower < l:
            lower += 1

        # upper = floor(sqrt(r))
        upper = math.isqrt(r)

        # If no prime squares exist in range, all numbers are non-special
        if lower > upper:
            return r - l + 1

        # Sieve of Eratosthenes up to upper (at most ~31623)
        is_prime = [True] * (upper + 1)
        if upper >= 0:
            is_prime[0] = False
        if upper >= 1:
            is_prime[1] = False

        for i in range(2, math.isqrt(upper) + 1):
            if is_prime[i]:
                for j in range(i * i, upper + 1, i):
                    is_prime[j] = False

        # Count primes in [lower, upper]
        special_count = 0
        for i in range(lower, upper + 1):
            if is_prime[i]:
                special_count += 1

        # Total numbers minus special numbers
        return (r - l + 1) - special_count

from typing import List

class Solution:
    def canReachCorner(self, xCorner: int, yCorner: int, circles: List[List[int]]) -> bool:
        n = len(circles)
        parent = list(range(n + 2))
        rank = [0] * (n + 2)

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(x, y):
            px, py = find(x), find(y)
            if px == py:
                return
            if rank[px] < rank[py]:
                px, py = py, px
            parent[py] = px
            if rank[px] == rank[py]:
                rank[px] += 1

        TOP_LEFT = n
        BOTTOM_RIGHT = n + 1

        for i in range(n):
            xi, yi, ri = circles[i]
            ri_sq = ri * ri

            tl = False
            br = False

            # Top edge (y = yCorner, 0 <= x <= xCorner)
            cx = xi if 0 <= xi <= xCorner else (0 if xi < 0 else xCorner)
            if (xi - cx) * (xi - cx) + (yi - yCorner) * (yi - yCorner) <= ri_sq:
                tl = True

            # Left edge (x = 0, 0 <= y <= yCorner)
            cy = yi if 0 <= yi <= yCorner else (0 if yi < 0 else yCorner)
            if xi * xi + (yi - cy) * (yi - cy) <= ri_sq:
                tl = True

            # Bottom edge (y = 0, 0 <= x <= xCorner)
            cx = xi if 0 <= xi <= xCorner else (0 if xi < 0 else xCorner)
            if (xi - cx) * (xi - cx) + yi * yi <= ri_sq:
                br = True

            # Right edge (x = xCorner, 0 <= y <= yCorner)
            cy = yi if 0 <= yi <= yCorner else (0 if yi < 0 else yCorner)
            if (xi - xCorner) * (xi - xCorner) + (yi - cy) * (yi - cy) <= ri_sq:
                br = True

            if tl:
                union(i, TOP_LEFT)
            if br:
                union(i, BOTTOM_RIGHT)

            if find(TOP_LEFT) == find(BOTTOM_RIGHT):
                return False

        for i in range(n):
            xi, yi, ri = circles[i]
            for j in range(i + 1, n):
                xj, yj, rj = circles[j]
                if (xi - xj) * (xi - xj) + (yi - yj) * (yi - yj) <= (ri + rj) * (ri + rj):
                    union(i, j)
                    if find(TOP_LEFT) == find(BOTTOM_RIGHT):
                        return False

        return True

