class Solution:
    def simulationResult(self, windows: List[int], queries: List[int]) -> List[int]:
        n = len(windows)
        seen = [False] * (n + 1)
        result = []

        # Process queries in reverse order to determine the final top-to-bottom order 
        # of the windows that were queried.
        for q in reversed(queries):
            if not seen[q]:
                result.append(q)
                seen[q] = True

        # Append the remaining windows that were never queried, 
        # preserving their original relative order.
        for w in windows:
            if not seen[w]:
                result.append(w)

        return result

