class Solution:
    def minFlips(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])

        base_cost = 0
        T_min = 0
        num_tied_2 = 0

        for i in range((m + 1) // 2):
            for j in range((n + 1) // 2):
                is_mid_i = (2 * i == m - 1)
                is_mid_j = (2 * j == n - 1)

                if is_mid_i and is_mid_j:
                    s = 1
                    ones = grid[i][j]
                elif is_mid_i:
                    s = 2
                    ones = grid[i][j] + grid[i][n - 1 - j]
                elif is_mid_j:
                    s = 2
                    ones = grid[i][j] + grid[m - 1 - i][j]
                else:
                    s = 4
                    ones = grid[i][j] + grid[i][n - 1 - j] + grid[m - 1 - i][j] + grid[m - 1 - i][n - 1 - j]

                min_cost = min(ones, s - ones)
                base_cost += min_cost

                if ones > s - ones:
                    T_min += s

                if s == 2 and ones == 1:
                    num_tied_2 += 1

        r = T_min % 4

        if r == 0:
            additional = 0
        elif r == 1:
            additional = 1
        elif r == 2:
            additional = 0 if num_tied_2 > 0 else 2
        else:  # r == 3
            additional = 1 if num_tied_2 > 0 else 3

        return base_cost + additional

