class Solution:
    def minCost(self, nums: List[int], k: int) -> int:
        n = len(nums)
        dp = [float('inf')] * (n + 1)
        dp[0] = 0

        for j in range(n):
            if dp[j] == float('inf'):
                continue
            freq = [0] * n
            unique_count = 0
            for i in range(j + 1, n + 1):
                num = nums[i - 1]
                if freq[num] == 0:
                    unique_count += 1
                elif freq[num] == 1:
                    unique_count -= 1
                freq[num] += 1

                cost = k + (i - j) - unique_count
                if dp[j] + cost < dp[i]:
                    dp[i] = dp[j] + cost

        return dp[n]

