class Solution:
    def findValidSplit(self, nums: List[int]) -> int:
        n = len(nums)

        # Sieve to find smallest prime factor for efficient factorization
        MAX_VAL = max(nums) + 1
        spf = list(range(MAX_VAL))
        for i in range(2, int(MAX_VAL**0.5) + 1):
            if spf[i] == i:  # i is prime
                for j in range(i * i, MAX_VAL, i):
                    if spf[j] == j:
                        spf[j] = i

        # Find last occurrence of each prime factor across the array
        last_occ = {}
        for i in range(n):
            val = nums[i]
            while val > 1:
                p = spf[val]
                last_occ[p] = i
                while val % p == 0:
                    val //= p

        # Sweep left to right, tracking the furthest last occurrence
        # of any prime factor seen so far
        cur_right = 0
        for i in range(n - 1):
            val = nums[i]
            while val > 1:
                p = spf[val]
                if last_occ[p] > cur_right:
                    cur_right = last_occ[p]
                while val % p == 0:
                    val //= p
            # If all prime factors seen so far end at or before i,
            # then no prime factor crosses the split boundary
            if cur_right <= i:
                return i

        return -1

