class Solution:
    def diagonalPrime(self, nums: List[List[int]]) -> int:
        def is_prime(n: int) -> bool:
            if n <= 1:
                return False
            if n <= 3:
                return True
            if n % 2 == 0 or n % 3 == 0:
                return False
            i = 5
            while i * i <= n:
                if n % i == 0 or n % (i + 2) == 0:
                    return False
                i += 6
            return True

        max_prime = 0
        n = len(nums)
        for i in range(n):
            val1 = nums[i][i]
            val2 = nums[i][n - 1 - i]

            if is_prime(val1) and val1 > max_prime:
                max_prime = val1
            if is_prime(val2) and val2 > max_prime:
                max_prime = val2

        return max_prime

