class Solution:
    def minimumVisitedCells(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])

        row_heaps = [[] for _ in range(m)]
        col_heaps = [[] for _ in range(n)]

        INF = 10**9

        for i in range(m):
            row_i = grid[i]
            r_heap = row_heaps[i]
            for j in range(n):
                if i == 0 and j == 0:
                    dp_val = 1
                else:
                    dp_val = INF

                    # Check minimum steps from the same row
                    while r_heap and r_heap[0][1] < j:
                        heapq.heappop(r_heap)
                    if r_heap:
                        dp_val = r_heap[0][0] + 1

                    # Check minimum steps from the same column
                    c_heap = col_heaps[j]
                    while c_heap and c_heap[0][1] < i:
                        heapq.heappop(c_heap)
                    if c_heap:
                        val = c_heap[0][0] + 1
                        if val < dp_val:
                            dp_val = val

                g = row_i[j]
                # If the cell is reachable and can make at least one move
                if dp_val != INF and g > 0:
                    heapq.heappush(r_heap, (dp_val, j + g))
                    heapq.heappush(col_heaps[j], (dp_val, i + g))

        return dp_val if dp_val != INF else -1

