        # Sort the ranges based on their starting points, and then by ending points
        ranges.sort()

        ans = []
        prev_end = -1

        for start, end in ranges:
            # If there is a gap between the previous covered range and the current one
            if start > prev_end + 1:
                ans.append([prev_end + 1, start - 1])

            # Update the end of the covered range to the maximum of current and previous
            if end > prev_end:
