        # Initialize the suffix frequency map
        for num in nums:
            suffix_count[num] = suffix_count.get(num, 0) + 1

        distinct_suffix = len(suffix_count)
        diff = []

        # Iterate through the array to compute the difference
        for num in nums:
            # Add current element to prefix set
            prefix_set.add(num)

            # Remove current element from suffix count
            suffix_count[num] -= 1
            if suffix_count[num] == 0:
                distinct_suffix -= 1

            # Calculate the difference and append to the result array
            diff.append(len(prefix_set) - distinct_suffix)

