class Solution:
    def maxMoves(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])

        # reachable[r] will be True if the cell (r, c) can be reached from the first column
        reachable = [True] * m

        for c in range(n - 1):
            next_reachable = [False] * m
            any_true = False

            for r in range(m):
                if reachable[r]:
                    val = grid[r][c]

                    # Move to (r - 1, c + 1)
                    if r > 0 and grid[r - 1][c + 1] > val:
                        if not next_reachable[r - 1]:
                            next_reachable[r - 1] = True
                            any_true = True

                    # Move to (r, c + 1)
                    if grid[r][c + 1] > val:
                        if not next_reachable[r]:
                            next_reachable[r] = True
                            any_true = True

                    # Move to (r + 1, c + 1)
                    if r < m - 1 and grid[r + 1][c + 1] > val:
                        if not next_reachable[r + 1]:
                            next_reachable[r + 1] = True
                            any_true = True

            # If no cell in the next column is reachable, we stop and return the current column index
            if not any_true:
                return c

            reachable = next_reachable

        # If we can reach the last column, the maximum moves is n - 1
        return n - 1

