class Solution:
    def countVisitedNodes(self, edges: List[int]) -> List[int]:
        n = len(edges)
        in_degree = [0] * n
        rev_adj = [[] for _ in range(n)]

        # Calculate in-degrees and build the reverse adjacency list
        for i in range(n):
            in_degree[edges[i]] += 1
            rev_adj[edges[i]].append(i)

        # Topological sort to peel off the tree parts and find the cycles
        queue = deque()
        for i in range(n):
            if in_degree[i] == 0:
                queue.append(i)

        while queue:
            u = queue.popleft()
            v = edges[u]
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

        answer = [0] * n
        cycle_queue = deque()

        # The remaining nodes with in_degree > 0 are part of the cycles
        for i in range(n):
            if in_degree[i] > 0 and answer[i] == 0:
                curr = i
                cycle_nodes = []
                # Traverse the cycle to find all its nodes and its length
                while answer[curr] == 0:
                    cycle_nodes.append(curr)
                    curr = edges[curr]

                cycle_len = len(cycle_nodes)
                for node in cycle_nodes:
                    answer[node] = cycle_len
                    cycle_queue.append(node)

        # Backward BFS to calculate the answer for the tree parts
        while cycle_queue:
            u = cycle_queue.popleft()
            for v in rev_adj[u]:
                if answer[v] == 0:
                    answer[v] = answer[u] + 1
                    cycle_queue.append(v)

        return answer

