        n = len(prices)
        ans = -1

        for j in range(1, n - 1):
            # Find max profit on the left with price < prices[j]
            max_left = -1
            for i in range(j):
                if prices[i] < prices[j]:
                    if profits[i] > max_left:
                        max_left = profits[i]

            # Find max profit on the right with price > prices[j]
            max_right = -1
            for k in range(j + 1, n):
                if prices[k] > prices[j]:
                    if profits[k] > max_right:
                        max_right = profits[k]

            # If valid triplet exists with j as middle element
            if max_left != -1 and max_right != -1:
                total = max_left + profits[j] + max_right
                if total > ans:
                    ans = total

        return ans

