class Solution:
    def minimumSum(self, nums: List[int]) -> int:
        n = len(nums)
        min_left = [0] * n

        # Precompute the minimum value to the left of each index
        current_min = float('inf')
        for i in range(n):
            min_left[i] = current_min
            if nums[i] < current_min:
                current_min = nums[i]

        ans = float('inf')
        # Track the minimum value to the right on the fly
        current_min = nums[-1]
        for j in range(n - 2, 0, -1):
            # Check if a valid mountain triplet can be formed with j as the peak
            if min_left[j] < nums[j] and current_min < nums[j]:
                ans = min(ans, min_left[j] + nums[j] + current_min)

            # Update the minimum value to the right for the next iteration
            if nums[j] < current_min:
                current_min = nums[j]

        return ans if ans != float('inf') else -1

