class Solution:
    def countCompleteSubstrings(self, word: str, k: int) -> int:
        n = len(word)
        ords = [ord(c) - ord('a') for c in word]

        # Split word into segments where adjacent chars differ by at most 2
        segments = []
        start = 0
        for i in range(1, n):
            if abs(ords[i] - ords[i - 1]) > 2:
                segments.append((start, i))
                start = i
        segments.append((start, n))

        result = 0

        for seg_start, seg_end in segments:
            L = seg_end - seg_start
            # Try all possible number of distinct characters: 1 to 26
            for num_chars in range(1, 27):
                window_len = num_chars * k
                if window_len > L:
                    break

                freq = [0] * 26
                valid_count = 0

                # Initialize first window
                for i in range(seg_start, seg_start + window_len):
                    c = ords[i]
                    if freq[c] == k:
                        valid_count -= 1
                    freq[c] += 1
                    if freq[c] == k:
                        valid_count += 1

                if valid_count == num_chars:
                    result += 1

                # Slide window across the segment
                for i in range(seg_start + window_len, seg_end):
                    # Add new character
                    c = ords[i]
                    if freq[c] == k:
                        valid_count -= 1
                    freq[c] += 1
                    if freq[c] == k:
                        valid_count += 1

                    # Remove old character
                    c = ords[i - window_len]
                    if freq[c] == k:
                        valid_count -= 1
                    freq[c] -= 1
                    if freq[c] == k:
                        valid_count += 1

                    if valid_count == num_chars:
                        result += 1

        return result

