class Solution:
    def divisibleTripletCount(self, nums: List[int], d: int) -> int:
        n = len(nums)
        if n < 3:
            return 0

        ans = 0

        # right_counts will store the frequencies of nums[k] % d for all k > j
        right_counts = {}
        for k in range(2, n):
            rem = nums[k] % d
            right_counts[rem] = right_counts.get(rem, 0) + 1

        # left_counts will store the frequencies of nums[i] % d for all i < j
        left_counts = {}
        left_counts[nums[0] % d] = 1

        # Iterate through all possible middle elements j
        for j in range(1, n - 1):
            target = (-nums[j]) % d

            # Count valid pairs (i, k) such that (nums[i] + nums[k]) % d == target
            for r, count in left_counts.items():
                needed = (target - r) % d
                if needed in right_counts:
                    ans += count * right_counts[needed]

            # Update right_counts: remove nums[j+1] since it will be the new j in the next iteration
            rem_j1 = nums[j+1] % d
            right_counts[rem_j1] -= 1
            if right_counts[rem_j1] == 0:
                del right_counts[rem_j1]

            # Update left_counts: add nums[j] since it will be a valid i for the next j
            rem_j = nums[j] % d
            left_counts[rem_j] = left_counts.get(rem_j, 0) + 1

        return ans

