import bisect

class Solution:
    def beautifulIndices(self, s: str, a: str, b: str, k: int) -> List[int]:
        def kmp_search(text, pattern):
            if not pattern or len(pattern) > len(text):
                return []
            # Build failure function
            fail = [0] * len(pattern)
            j = 0
            for i in range(1, len(pattern)):
                while j > 0 and pattern[i] != pattern[j]:
                    j = fail[j - 1]
                if pattern[i] == pattern[j]:
                    j += 1
                fail[i] = j

            # Search for pattern in text
            result = []
            j = 0
            for i in range(len(text)):
                while j > 0 and text[i] != pattern[j]:
                    j = fail[j - 1]
                if text[i] == pattern[j]:
                    j += 1
                if j == len(pattern):
                    result.append(i - len(pattern) + 1)
                    j = fail[j - 1]
            return result

        indices_a = kmp_search(s, a)
        indices_b = kmp_search(s, b)

        if not indices_b:
            return []

        result = []
        for i in indices_a:
            # Binary search for the closest index in indices_b
            pos = bisect.bisect_left(indices_b, i)
            found = False
            # Check the element at pos (j >= i)
            if pos < len(indices_b) and indices_b[pos] - i <= k:
                found = True
            # Check the element at pos - 1 (j <= i)
            if pos > 0 and i - indices_b[pos - 1] <= k:
                found = True
            if found:
                result.append(i)

        return result

