class Solution:
    def countMatchingSubarrays(self, nums: List[int], pattern: List[int]) -> int:
        n = len(nums)
        m = len(pattern)

        # Create an array representing the relationship between adjacent elements
        # 1 if increasing, 0 if equal, -1 if decreasing
        rel = [(b > a) - (b < a) for a, b in zip(nums, nums[1:])]

        # Compute the LPS (Longest Prefix Suffix) array for the KMP algorithm
        lps = [0] * m
        length = 0
        i = 1
        while i < m:
            if pattern[i] == pattern[length]:
                length += 1
                lps[i] = length
                i += 1
            else:
                if length != 0:
                    length = lps[length - 1]
                else:
                    lps[i] = 0
                    i += 1

        # KMP search algorithm to find occurrences of pattern in rel
        count = 0
        i = 0  # index for rel
        j = 0  # index for pattern
        while i < n - 1:
            if pattern[j] == rel[i]:
                i += 1
                j += 1

            if j == m:
                count += 1
                j = lps[j - 1]
            elif i < n - 1 and pattern[j] != rel[i]:
                if j != 0:
                    j = lps[j - 1]
                else:
                    i += 1

        return count

