class Solution:
    def minOperationsToMakeMedianK(self, nums: List[int], k: int) -> int:
        nums.sort()
        n = len(nums)
        m = n // 2

        ops = 0

        # For elements before the median index, they must be <= k.
        # If any element is greater than k, we must decrease it to k.
        for i in range(m):
            if nums[i] > k:
                ops += nums[i] - k

        # The median element itself must be exactly k.
        ops += abs(nums[m] - k)

        # For elements after the median index, they must be >= k.
        # If any element is less than k, we must increase it to k.
        for i in range(m + 1, n):
            if nums[i] < k:
                ops += k - nums[i]

        return ops

