class Solution:
    def countOfPeaks(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums)

        # BIT (1-indexed)
        bit = [0] * (n + 1)

        def update(i, delta):
            while i <= n:
                bit[i] += delta
                i += i & (-i)

        def query(i):
            s = 0
            while i > 0:
                s += bit[i]
                i -= i & (-i)
            return s

        def range_query(l, r):
            if l > r:
                return 0
            return query(r) - query(l - 1)

        def is_peak(i):
            return nums[i] > nums[i - 1] and nums[i] > nums[i + 1]

        # Track peak status for each index
        peak_status = [False] * n
        for i in range(1, n - 1):
            if is_peak(i):
                peak_status[i] = True
                update(i + 1, 1)  # 1-indexed BIT position

        def reevaluate(i):
            if i <= 0 or i >= n - 1:
                return
            new_status = is_peak(i)
            if new_status != peak_status[i]:
                if new_status:
                    update(i + 1, 1)
                else:
                    update(i + 1, -1)
                peak_status[i] = new_status

        result = []
        for q in queries:
            if q[0] == 1:
                l, r = q[1], q[2]
                # Peaks can only be at array indices l+1 to r-1
                # In 1-indexed BIT, that's positions l+2 to r
                if l + 1 > r - 1:
                    result.append(0)
                else:
                    result.append(range_query(l + 2, r))
            else:
                idx, val = q[1], q[2]
                nums[idx] = val
                # Re-evaluate peak status for affected neighbors
                reevaluate(idx - 1)
                reevaluate(idx)
                reevaluate(idx + 1)

        return result

