    def tripletCount(self, a: List[int], b: List[int], c: List[int]) -> int:
        def count_parity(arr):
            even = 0
            odd = 0
            for x in arr:
                if bin(x).count('1') % 2 == 0:
                    even += 1
                else:
                    odd += 1
            return even, odd

        even_a, odd_a = count_parity(a)
        even_b, odd_b = count_parity(b)
        even_c, odd_c = count_parity(c)

        return (even_a * even_b * even_c + 
                even_a * odd_b * odd_c + 
                odd_a * even_b * odd_c + 
                odd_a * odd_b * even_c)

class Solution:
    def maxScore(self, nums: List[int]) -> int:
        n = len(nums)
        dp = [0] * n
        for j in range(1, n):
            for i in range(j):
                dp[j] = max(dp[j], dp[i] + (j - i) * nums[j])
        return dp[n - 1]

from typing import List

class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:
        ans = 0
        # prev stores the mapping of {and_value: count} for subarrays ending at the previous index
        prev = {}

        for x in nums:
            curr = {x: 1}
            # Calculate the new AND values by extending the previous subarrays with the current number `x`
            for val, cnt in prev.items():
                new_val = val & x
                if new_val in curr:
                    curr[new_val] += cnt
                else:
                    curr[new_val] = cnt

            # Move to the next position
            prev = curr

            # If `k` is among the possible AND values of subarrays ending at the current index, add its count
            ans += prev.get(k, 0)

        return ans

class Solution:
    def tripletCount(self, a: List[int], b: List[int], c: List[int]) -> int:
        def count_parity(arr):
            even = 0
            odd = 0
            for x in arr:
                if x.bit_count() % 2 == 0:
                    even += 1
                else:
                    odd += 1
            return even, odd

        even_a, odd_a = count_parity(a)
        even_b, odd_b = count_parity(b)
        even_c, odd_c = count_parity(c)

        return (even_a * even_b * even_c + 
                even_a * odd_b * odd_c + 
                odd_a * even_b * odd_c + 
                odd_a * odd_b * even_c)

# Definition for singly-linked list.
# class ListNode:
#     def __init__(self, val=0, next=None):
#         self.val = val
#         self.next = next
class Solution:
    def modifiedList(self, nums: List[int], head: Optional[ListNode]) -> Optional[ListNode]:
        nums_set = set(nums)
        dummy = ListNode(0, head)
        current = dummy

        while current.next:
            if current.next.val in nums_set:
                current.next = current.next.next
            else:
                current = current.next

        return dummy.next
